INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (1,1,'Ação de risco / Risk Action. Uma tarefa detalhada que implementa, no todo ou em parte, uma estratégia de resposta para resolver um risco individual ou geral.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (2,2,'Aceitação do risco / Risk Acceptance. Uma resposta ao risco que envolve o seu reconhecimento, mas nada fazer, a não ser que o risco ocorra.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (3,4,'Ameaça / Threat. Um risco que teria um efeito negativo em um ou mais objetivos. Ver também questão, oportunidade e risco.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (4,5,'Análise dos riscos / Risk Analysis. As atividades relacionadas à definição das características de um risco e o grau em que pode impactar os objetivos.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (5,6,'Análise qualitativa dos riscos / Qualitative Risk Analysis. A consideração de uma gama de características como probabilidade de ocorrência, grau de impacto sobre os objetivos, capacidade de gerenciamento, oportunidade de possíveis impactos, relações com os takeholders, dentre outros.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (6,7,'Análise quantitativa dos riscos / Quantitative Risk Analysis. O efeito combinado de riscos identificados no resultado desejado.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (7,8,'Apetite ao risco / Risk Appetite. O grau de incerteza que uma organização ou um indivíduo está disposto a aceitar em expectativa de uma recompensa. Ver também limites dos riscos e tolerância ao risco.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (8,9,'Atitude ao risco / Risk Attitude. Uma atitude frente à incerteza, adotada explícita ou implicitamente por indivíduos e grupos, impulsionada pela percepção e evidenciada pelo comportamento observável.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (9,10,'Aumento de riscos / Risk Enhancement. Uma resposta ao risco que envolve aumentar a probabilidade da ocorrência ou do impacto de uma oportunidade.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (10,11,'Avaliação do risco / Risk Assessment. O processo de identificação, análise e determinação da probabilidade de ocorrência de um risco.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (11,12,'Causa / Cause. Eventos ou circunstâncias que existem atualmente ou que certamente existirão no futuro e que podem dar origem a riscos.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (12,13,'Ciclo de vida de gerenciamento de riscos / Risk Management Life Cycle. Uma abordagem estruturada para realizar uma visão abrangente do risco no âmbito geral da empresa, nos domínios do portfólio, programa e projeto.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (13,14,'Compartilhamento de risco / Risk Sharing. Uma resposta ao risco que envolve a alocação de responsabilidade de uma oportunidade a um terceiro melhor qualificado para capturar a oportunidade ou absorver o impacto da ameaça.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (15,15,'Componente / Component. Um elemento predeterminado de um portfólio ou programa relacionado ao trabalho para o atingimento dos objetivos estratégicos do portfólio ou programa.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (16,16,'Condição de gatilho / Trigger Condition. Um evento ou situação que indica que um risco está prestes a ocorrer.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (17,18,'Controle  Eficaz. O controle será considerado eficaz quando atender a sua finalidade na totalidade.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (18,19,'Controle  Ineficaz. O controle será considerado ineficaz quando não atender a sua finalidade na totalidade.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (19,23,'Escalação de riscos / Risk Escalation. Uma resposta ao risco que envolve a transferência da propriedade do risco a uma pessoa relevante da organização porque o risco está fora do escopo ou a equipe não tem autoridade suficiente para endereçá-lo.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (20,24,'Estratégia de resposta / Response Strategy. Uma abordagem de alto nível para resolver um risco individual ou geral, dividido em um conjunto de ações contra o risco.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (21,25,'Evento. É uma ocorrência ou conjunto de circunstâncias específicas que pode afetar a realização dos objetivos de uma organização. Esses eventos podem ser tanto internos quanto externos e podem ser positivos (oportunidades) ou negativos (ameaças).','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (22,27,'Exploração de risco / Risk Exploiting. Uma resposta ao risco que envolve garantir que uma oportunidade ocorra. Ver também aceitação do risco, prevenção de riscos, aumento de riscos, mitigação de riscos, compartilhamento de risco e transferência dos riscos.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (23,28,'Exposição ao risco / Risk Exposure. Uma medida total do impacto potencial de todos os riscos em qualquer determinado estágio em um projeto, programa ou portfólio.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (24,29,'Fator de Risco. É  uma causa interna ou externa que impulsiona os riscos potenciais e afeta a implementação da estratégia, assim como o cumprimento dos objetivos organizacionais.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (25,30,'Fixação de objetivos. É uma precondição à identificação de eventos, à avaliação de riscos e às respostas a riscos. É necessário que os objetivos existam para que a O M possa identificar eavaliar os riscos quanto a sua realização, bem como adotar as medida','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (27,32,'Fonte de Risco Administrativa. Refere-se a qualquer aspecto relacionado à gestão e à organização interna de uma empresa que possa gerar vulnerabilidades, falhas ou desafios operacionais. Isso pode incluir: Gestão Ineficaz,  Processos Operacionais, dentre ','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (28,33,'Fonte de Risco Ambiental. Qualquer elemento ou fenômeno associado ao meio ambiente natural que possa ameaçar uma organização. Isso inclui aspectos legais e regulatórios relacionados às normas ambientais, bem como expectativas das partes interessadas em re','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (29,34,'Fonte de Risco Econômico. Qualquer fator ou evento relacionado à economia que possa afetar negativamente uma organização. Isso pode incluir:Ciclos Econômico; Instabilidade Macroeconômica; Condições de Mercado; Riscos Financeiros; e Política Econômica.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (30,35,'Fonte de Risco Material. Qualquer elemento físico ou condição tangível que possa representar uma ameaça à segurança, operação ou ativos de uma organização. Isso inclui equipamentos, instalações, infraestrutura de TI, mobiliário, equipamentos, material.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (31,36,'Fonte de Risco Operacional. Refere-se a qualquer elemento dentro das operações de uma organização que possa causar perdas devido a falhas em processos internos, sistemas, pessoal ou eventos externos. Isso pode incluir: Processos Internos; Pessoas e Gestão','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016 (Adaptado pelo autor)');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (32,37,'Fonte de Risco Política. Qualquer fator relacionado ao ambiente político que pode impactar negativamente uma organização. Isso inclui: Instabilidade Política; Regulamentação; Riscos Geopolíticos; Governança; e Percepção Pública.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (33,38,'Fonte de Risco Social. Qualquer aspecto relacionado às dinâmicas sociais e culturais que possa impactar negativamente uma organização.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (34,39,'Fonte de Risco Tecnológica. Qualquer aspecto relacionado à tecnologia que possa representar uma ameaça ou u desafio para a organização.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (35,41,'Framework de gerenciamento de riscos / Risk Management Framework. Uma estrutura que organiza o processo e as atividades de gerenciamento de riscos de forma iterativa.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (36,42,'Gatilho/ Trigger. Um evento ou situação que indica que um risco está prestes a ocorrer','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (37,43,'Gerenciamento de portfólio / Portfolio Management. O gerenciamento centralizado de um ou mais portfólios para alcançar os objetivos estratégicos. Ver também gerenciamento de programas e gerenciamento de projetos.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (38,44,'Gerenciamento de programas / Program Management. A aplicação de conhecimentos, habilidades e princípios a um programa para realizar os objetivos do programa e obter benefícios e controle de outra forma não disponíveis através do gerenciamento individual dos projetos.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (39,45,'Gerenciamento de projetos / Project Management. A aplicação de conhecimentos, habilidades, ferramentas e técnicas às atividades do projeto a fim de atender aos seus requisitos. Ver também gerenciamento de portfólio e gerenciamento de programas.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (40,46,'Gerenciamento de projetos organizacional / Organizational Project Management. Uma estrutura na qual o gerenciamento de portfólios, programas e projetos são integrados com os habilitadores organizacionais paraalcançar objetivos estratégicos.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (41,47,'Gerenciamento de risco empresarial / Enterprise Risk Management. Uma abordagem para gerenciar o risco que reflete a cultura, a capacidade e a estratégia da organização para criar e sustentar valor.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (42,48,'Gerenciamento de riscos / Risk Management. O processo que molda a tomada de decisão para toda a organização e em cada um dos domínios e envolve a identificação, análise, resposta e o monitoramento dos riscos.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (44,49,'Identificação de riscos / Risk Identification. O processo de localização e detalhamento das características dos riscos relacionados aos objetivos do trabalho.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (45,50,'Identificar os riscos / Identify Risks. Processo que determina e documenta os riscos que podem afetar os resultados pretendidos.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (46,51,'Impacto / Impact. Uma medida do efeito de um risco em um ou mais objetivos, caso ocorra.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (47,52,'Impacto Alto. Interrupção de operações, atividades, projetos, programas ou processos da organização, causando impactos de difícil reversão nos objetivos.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (48,53,'Impacto Baixo. Degradação de operações, atividades, projetos, programas ou processos da organização, causando impactos pequenos nos objetivos.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (49,54,'Impacto Médio. Interrupção de operações ou atividades da organização, de projetos, programas ou processos, causando impactos significativos nos objetivos, porém recuperáveis','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (50,55,'Impacto Muito Alto. Interrupção abrupta de operações, atividades, projetos, programas ou processos da organização, impactando fortemente outros processos, causando impactos de muito difícil reversão nos objetivos.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (51,56,'Impacto Muito Baixo. Degradação de operações, atividades, projetos, programas ou processos da organização, porém causando impactos mínimos nos objetivos (de tempo, prazo, custo, quantidade, qualidade, acesso, escopo, imagem etc) relacionados ao atendimento de metas, padrões ou à capacidade de entrega de produtos/serviços às partes interessadas (clientes internos/externos e beneficiários).','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (52,58,'Limites dos riscos / Risk Threshold. A medida da variação aceitável em torno de um objetivo que reflete o apetite de risco da organização e suas partes interessadas. Veja também apetite de risco. Ver também apetite ao risco e tolerância ao risco.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (53,59,'Mitigação de riscos / Risk Mitigation. Uma resposta ao risco que envolve reduzir a probabilidade ou o impacto de uma ameaça. Ver também aceitação do risco, revenção de riscos, aumento de riscos, exploração de risco, compartilhamento de risco e transferênc','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (54,60,'Nível de Rsco . Expressa a criticidade ou magnitude de um determinado evento derisco, decorrente da combinação de seu impacto e probabil idade de ocorrência e deve ser mensuradodurante a etapa de avaliação do risco.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (55,61,'Oportunidade / Opportunity. Um risco que teria um efeito positivo em um ou mais objetivos. Ver também questão, risco e ameaça.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (56,62,'Parte interessada / Stakeholder. Um indivíduo, grupo ou organização que possa afetar, ser afetado, ou sentir-se afetado por uma decisão, atividade, ou resultado de um projeto, programa ou portfólio.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (57,63,'Plano de contingência / Contingency Plan. Um documento que descreve as ações a serem tomadas caso ocorram condições de gatilho predeterminadas.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (58,64,'Plano de gerenciamento dos riscos / Risk Management Plan. Um componente do plano de gerenciamento do projeto, programa ou portfólio que descreve como as atividades de gerenciamento de riscos serão estruturadas e executadas.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (59,65,'Portfólio / Portfolio. Projetos, programas, subportfólios e operações gerenciadas em grupo para alcançar objetivos estratégicos. Ver também programa e projeto.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (60,66,'Premissa / Assumption. Um fator do processo de planejamento considerado verdadeiro, real ou certo, sem a necessidade de prova ou demonstração.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (61,67,'Prevenção de riscos / Risk Avoidance. Uma resposta ao risco que envolve eliminar a ameaça ou proteger o projeto, programa ou portfólio de seu impacto. Ver também aceitação do risco, aumento de riscos, exploração de risco, mitigação de riscos, compartilham','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (62,68,'Prioridade de Tratamento  Ação de Curto e Médio Prazo. Uma ação de curto e médio prazo de tratamento de riscos é uma medida planejada e implementada ao longo de um período definido, que geralmente abrange alguns meses até cerca de um ano, com o objetivo de reduzir ou mitigar os riscos identificados. Essas ações são desenvolvidas como parte de uma estratégia de gerenciamento de riscos mais abrangente e são projetadas para lidar com ameaças ou aproveitar oportunidades que requerem intervenções mais elaboradas do que simples ações imediatas..','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (63,69,'Prioridade de Tratamento  Ação Imediata. É uma medida rápida e decisiva implementada logo após a identificação de um risco significativo. Essa ação tem como objetivo mitigar ou eliminar imediatamente a ameaça ou aproveitar uma oportunidade, minimizando seus impactos potenciais.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (64,70,'Prioridade de Tratamento Monitoramento e Gestão. As ações de monitoramento e gestão para tratamento de riscos referem-se às atividades contínuas realizadas para acompanhar e controlar a eficácia das medidas implementadas para lidar com os riscos identificados. Normalmente adota-se essa conduta quando os riscos são classificados como baixos.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (65,71,'Prioridade de Tratamento Risco controlado. Essa medida compreende a aplicação de controles ou precauções adicionais que auxiliam na redução ou eliminação do risco, permitindo à organização manter um nível de exposição aos riscos considerado aceitável. Geralmente, essa ação é tomada quando o risco está sob controle da organização e não representa uma ameaça ao processo subjacente.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (66,72,'Probabilidade  Baixa. Evento casual, inesperado. Muito embora raro, há histórico conhecido de sua de ocorrência por parte dos principais gestores e operadores do processo','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (67,73,'Probabilidade / Probability. Uma medida do nível de possibilidade de ocorrer um risco individual.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (68,74,'Probabilidade Alta. Evento usual, corriqueiro. Devido à sua ocorrência habitual ou conhecida em uma dezena ou mais de casos, aproximadamente, seu histórico é amplamente conhecido por parte de gestores e operadores do processo','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (70,75,'Probabilidade Média. Evento esperado, que se reproduz com frequência reduzida, porém constante. Seu histórico de ocorrência é de conhecimento da maioria dos gestores e operadores do processo.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (71,76,'Probabilidade Muito Alta. Evento se reproduz muitas vezes, se repete seguidamente, de maneira assídua, numerosa e, não raro, de modo acelerado. Interfere de modo claro no ritmo das atividades, sendo evidente para os que conhecem o processo.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (72,77,'Probabilidade Muito Baixa. Evento extraordinário para os padrões conhecidos da gestão e operação do processo. Embora possa assumir dimensão estratégica para a manutenção do processo, não há histórico disponível de sua ocorrência.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (73,79,'Programa / Program. Um grupo relacionado de projetos, subprogramas e atividades de programa gerenciad de forma coordenada para a obtenção de benefícios que não estariam disponíveis se eles fossem gerenciados individualmente. Ver também portfólio e projeto','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (74,80,'Projeto / Project. Um esforço temporário empreendido para criar um produto, serviço ou resultado único. Ver também portfólio e programa.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (75,81,'Questão / Issue. Uma ameaça atual que pode ter um impacto em um ou mais objetivos. Ver também oportunidade, risco e ameaça.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (76,82,'Registro dos riscos / Risk Register. Um repositório no qual são registradas as saídas de processos de gerenciamento dos riscos.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (77,83,'Reserva de contingência / Contingency Reserve. Tempo ou dinheiro alocado no cronograma ou linha de base dos custos para riscos conhecidos com estratégias de resposta ativa. Ver também reserva gerencial.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (78,84,'Reserva gerencial / Management Reserve. Tempo ou dinheiro que a gerência reserva além do cronograma ou da linha de base de custos e libera para trabalho imprevisto, contido no âmbito do escopo do projeto. Ver também reserva de contingência.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (79,85,'Responsável da ação de risco / Risk Action Owner. A(s) pessoa(s) responsável(is) por executar as ações de risco aprovadas em resposta a um determinado risco. Também conhecido como dono da resposta.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (80,86,'Responsável pelo risco/ Proprietário do Risco/ Risk Owner. A pessoa responsável por monitorar o risco e por selecionar e implementar uma estratégia adequada de resposta a risco.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (81,87,'Resposta ao risco / Risk Response. Uma ação, planejada ou implementada, para resolver ameaças e oportunidades específicas.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (82,88,'Restrição / Constraint. Um fator que limita as opções de gerenciamento de um projeto, programa, portfólio ou processo.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (83,89,'Risco / Risk. Um evento ou condição incerta que, se ocorrer, provocará um efeito positivo ou negativo em um ou mais objetivos. Ver também questão, oportunidade e ameaça.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (84,90,'Risco Alto. Nível de  Risco que pode ser tanto um risco provável, que possui alta probabilidade de ocorrência e baixo impacto na consecução dos objetivos, bem como um risco inesperado, que possui baixa probabilidade de ocorrência e alto impacto na','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (85,91,'Risco Baixo. Nível de  Risco que causa pouco prejuízo, necessitando apenas de atividades de monitoramento devido à relação custo/benefício de implantar controles.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (86,92,'Risco de Gestão Interna.Tipo de risco que pode comprometer os objetivos e as atividades administrativas das OM, normalmente associados a falhas, deficiências ou inadequação de processos internos de gestão de recursos organizacionais, dentre os quais, obri','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (87,93,'Risco de Integridade. Risco que configura ações ou omissões intencionais que possam favorecer a ocorrência de fraudes ou atos de corrupção, podendo ser causa, evento ou consequência de outros riscos.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (88,94,'Risco emergente / Emergent Risk. Um risco que surge de novas circunstâncias, mudanças no ambiente, ações de risco realizadas e ou eventos inesperados que não foram previstos anteriormente ou que não faziam parte do escopo inicial de análise de riscos.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (89,95,'Risco Estratégico. Tipo de risco  que pode  impedir ou dificultar a execução do Plano Estratégico do Exército (PEEx) na consecução dos Objetivos Estratégicos do Exército (OEE) e Objetivos Estratégicos Setoriais (OES).','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (90,96,'Risco Extremo. Nível de  Risco inaceitável, que possui alta probabilidade de ocorrência e poderá resultar em impacto extremamente severo caso ocorra. Exige tratamento imediato, de modo a evitar, eliminar ou atenuar urgentemente as causas e/ou efeitos deco','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (91,97,'Risco geral / Overall Risk. O efeito da incerteza sobre o portfólio, programa ou projeto como um todo.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (93,98,'Risco Médio. Nível de Risco que necessita de atividades de monitoramento a fim de mantê-lo neste nível ou de tratamento sem custos adicionais.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (94,99,'Risco Operativo. Tipo de risco que  pode impedir ou dificultar a realização de atividades eminentemente militares pela Força Terrestre (F Ter).','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (95,100,'Risco Residual / Residual Risk. O risco que continua a existir mesmo após as respostas ao risco terem sido implementadas. Ver também risco secundário.','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (96,101,'Risco Secundário / Secondary Risk. Um risco que surge como resultado direto da implementação de uma resposta aos riscos. Ver também risco residual e risco emergente..','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (97,103,'Transferência dos riscos / Risk Transference. Uma resposta ao risco que envolve transferir o impacto de uma ameaça para um terceiro, junto com a responsabilidade da resposta. Ver também aceitação do risco, prevenção de riscos, aumento de riscos, exploraçã','The Standard for Risk Management in Portfolios, Programs, and Projects, PMI, 2ª Ed, 2019');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (99,40,'Fonte de Risco. Elemento que, individualmente ou combinado, tem o potencial para dar origem ao risco','ABNT NBR ISO 31000 - Gestão de riscos ― Diretrizes - 2018');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (100,17,'Consequências. Resultado de um evento que afeta os objetivos. Uma consequência pode ser certa ou incerta e pode ter efeitos positivos ou negativos, diretos ou indiretos, nos objetivos. Qualquer consequência pode escalar por meio de efeitos cascata e cumulativos.','ABNT NBR ISO 31000 - Gestão de riscos ― Diretrizes - 2018');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (101,26,'Evento. ocorrência ou mudança em um conjunto específico de circunstâncias. Um evento pode consistir em uma ou mais ocorrências e pode ter várias causas e várias consequências.','ABNT NBR ISO 31000 - Gestão de riscos ― Diretrizes - 2018');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (102,78,'Probabilidade. Chance de algo acontecer. A palavra “probabilidade” é utilizada para referir-se à chance de algo acontecer, não importando se definida, medida ou determinada, ainda que objetiva ou subjetivamente, qualitativa ou quantitativamente, e se descrita utilizando-se termos gerais ou matemáticos.','ABNT NBR ISO 31000 - Gestão de riscos ― Diretrizes - 2018');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (103,22,'Controle. Medida que mantém e/ou modifica o risco. Controles incluem, mas não estão limitados a qualquer processo, política, dispositivo, prática, ou outras condições e/ou ações que mantêm e/ou modificam o risco.','ABNT NBR ISO 31000 - Gestão de riscos ― Diretrizes - 2018');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (104,102,'Risco. Efeito da incerteza nos objetivo. Um efeito é um desvio em relação ao esperado. Pode ser positivo, negativo ou ambos, e pode abordar, criar ou resultar em oportunidades e ameaças. Risco é normalmente expresso em termos de fontes de risco, eventos potenciais, suas consequências e suas probabilidades.','ABNT NBR ISO 31000 - Gestão de riscos ― Diretrizes - 2018');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (105,21,'Controle Preventivo. Desenhado para prevenir a ocorrência de eventos indesejáveis. Reduz a probabilidade de os fatores de risco virem a contribuir para a concretização desses eventos.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (106,20,'Controle de Detecção. Desenhado para detectar eventos indesejados. Aponta a manifestação/ocorrência de um risco, sendo necessário um plano de contingência para atenuar o impacto nos objetivos do processo.','Manual Técnico (EB20-MT-11.002) Gestão de Processos, EME, 2016');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (110,3,'Ambiente Interno. O ambiente interno compreende o tom de uma organização e fornece a base pela qual os riscos são identificados e abordados pelo seu pessoal, inclusive a filosofia de gerenciamento de riscos, o apetite a risco, a integridade e os valores éticos, além do ambiente em que estes estão.','COSO - Gerenciamento de Riscos Corporativos - Aplicando o gerenciamento de riscos corporativos aos riscos relacionados ao ambiental, social e governança - 2018');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (111,31,'Fixação de Objetivos. Os objetivos devem existir antes que a administração possa identificar os eventos em potencial que poderão afetar a sua realização. O gerenciamento de riscos corporativos assegura que a administração disponha de um processo implementado para estabelecer os objetivos que propiciem suporte e estejam alinhados com a missão da organização e sejam compatíveis com o seu apetite a riscos.','COSO - Gerenciamento de Riscos Corporativos - Aplicando o gerenciamento de riscos corporativos aos riscos relacionados ao ambiental, social e governança - 2018');
INSERT INTO "t_025_glossario_de_termos" ("codigo", "codtermo", "termo", "fonte") VALUES (112,57,'Integridade. A qualidade ou o estado de possuir princípios morais íntegros; retidão, honestidade e sinceridade; o desejo de fazer aquilo que é certo, professar e viver de acordo com uma série de valores e expectativas.','COSO - Gerenciamento de Riscos Corporativos - Aplicando o gerenciamento de riscos corporativos aos riscos relacionados ao ambiental, social e governança - 2018');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (1,'- Realizar treinamento da equipe em Segurança do Trabalho, com ênfase na NR-18');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (2,'- Realizar treinamento da equipe em Licitações e Contratos Públicos, com ênfase na NLL 14.133');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (3,'- Capacitar e treinar a equipe de fiscalização da obra, proporcionando meios e condições necessárias para o desempenho adequado dessa função.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (4,'- Realizar auditorias de riscos frequentes nas atividades críticas');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (5,'- Divulgar e fazer cumprir a metodologia de gerenciamento de projetos na organização.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (6,'- Divulgar e fazer cumprir a metodologia de gestão de riscos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (7,'- Revisar  os projetos em fase de obra (RPFA)');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (8,'- Revisar o Termo de Cooperação.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (9,'- Elaborar Planos de Trabalho com estimativas realistas de prazo, custo e escopo, incluindo incluindo mecanismos de resolução de disputas e procedimentos para aditivos de prazo, custo e escopo');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (10,'- Redigir um novo PTRAB');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (11,'- Solicitar aprovações no GptE, DOC e CONJUR');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (12,'- Elaborar Instrumentos de Parceria com redação clara e precisa das cláusulas contratuais, incluindo mecanismos de resolução de disputas e procedimentos para aditivos contratuais');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (13,'- Criar um programa de manutenção preventiva no canteiro.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (14,'- Realizar um plano de recompletmento de Força de Trabalho');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (15,'- Realizar um programa de conscientização a respeito daLei 12.846 - responsabilização administrativa e civil de pessoas jurídicas pela prática de atos contra a administração pública, nacional ou estrangeira');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (16,'- Realizar um plano de segregação de funções nas atividades críticas dos processo');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (17,'- Realizar treinamento da equipe em Legislação Ambiental');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (18,'- Realizar treinamento da equipe em Legislação Sanitária');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (19,'- Padronizar processos e procedimentos administrativos');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (20,'- Realizar auditorias internas frequentes nas áreas específicas de licitações e contratos, patrimônio imobiliário e meio ambiente');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (21,'- Desenvolver e implementar programa de qualidade nos canteiros de obras.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (22,'- Designar uma equipe de supervisão e fiscalização competente e experiente para acompanhar o andamento da obra.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (23,'- Estabelecer reuniões periódicas para discutir o progresso do projeto, controle dos riscos e abordar quaisquer problemas ou preocupações rapidamente');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (24,'- Corrigir eventuais problemas de projeto antes que eles se tornem fontes de atraso.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (25,'- Desenvolver e implementar planos de contingência que considerem a possibilidade de atrasos e força maior.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (26,'- Manter registros detalhados de todas as comunicações, alterações no escopo, decisões e eventos que possam afetar o cronograma do projeto');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (27,'- Evitar inscrever empenhos em Restos a Pagar Não Processados (RPNP)');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (28,'- Estabelecer um processo de monitoramento contínuo para verificar a conformidade trabalhista ao longo do contrato, englobando a documentação trabalhista e as condições de saúde e segurança do trabalho');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (29,'- Realizar uma avaliação ambiental detalhada antes de iniciar a obra para identificar possíveis impactos ambientais e desenvolver estratégias de mitigação');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (30,'- Manter diálogo constante com as autoridades ambientais, comunicando atividades planejadas e obtendo aprovações conforme necessário');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (31,'- Dispor de um plano de contingência ambiental preparado para responder rapidamente a emergência ambiental e minimizar seus impactos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (32,'- Manter registros detalhados de todas as ações tomadas para mitigar impactos ambientais e garantir conformidade');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (33,'- Contratar profissionais independentes para revisar e validar o Projeto Básico, identificando potenciais problemas antes do início da obra.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (34,'- Efetuar revisões técnicas e avaliações cuidadosas do projeto executivo antes de sua implementação');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (35,'- Analisar os projetos executivos elaborados pelo Concedente, permitindo identificar eventuais problemas ou desalinhamentos antes do início da execução da obra.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (36,'- Antes de iniciar o projeto, realizar uma análise detalhada dos requisitos e regulamentos dos órgãos de fiscalização e concessionárias.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (37,'- Efetuar uma avaliação detalhada dos riscos naturais específicos da área antes de iniciar a obra, incluindo estudos hidrogeológicos, e meteorológicos para identificar as ameaças potenciais');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (38,'- Planejar e projetar a obra de forma a minimizar os danos em caso de evento natural adverso');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (39,'- Garantir que as equipes de fiscalização e as empresas empresa Contratadas sejam adequadamente treinadas em segurança no trabalho');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (40,'- Ter procedimentos claros e treinados de resposta a acidentes');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (41,'- Planejar detalhadamente as necessidades de insumos, equipamentos e produtos com antecedência, considerando prazos, quantidades e especificações');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (42,'- Manter um monitoramento constante do progresso da entrega de insumos e equipamentos, identificando potenciais problemas logísticos de forma precoce');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (43,'- Desenvolver e implementar planos de contingência que incluam alternativas para lidar com atrasos ou problemas logísticos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (44,'- Proceder uma análise detalhada dos riscos regulatórios e legais envolvidos no projeto desde o início');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (45,'- Familiarizar-se com as regulamentações e diretrizes estabelecidas pelos órgãos de fiscalização e concessionárias relevantes, ajudando a antecipar possíveis mudanças no projeto');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (46,'- Proceder uma análise detalhada das condições climáticas históricas na área do projeto, permitindo prever períodos prováveis de condições adversas e planejar de acordo');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (47,'- Incluir margens de tempo adicionais no cronograma pelo órgão Contratante para acomodar a possibilidade de falhas de equipamento');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (48,'- Implantar um processo estruturado para avaliar e aprovar alterações no escopo do projeto');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (49,'- Proceder uma pesquisa detalhada das licenças e permissões necessárias para o projeto antes do início da construção');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (50,'- Elaborar planos detalhados que atendam aos requisitos das licenças e permissões, incluindo medidas de mitigação de impactos ambientais e de segurança');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (51,'- Manter um acompanhamento constante do status das solicitações de licenças e permissões, garantindo que todos os prazos sejam atendidos e que qualquer ação necessária seja tomada');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (52,'- Desenvolver e implementar planos de contingência que considerem possíveis atrasos na obtenção das licenças e permissões e como esses atrasos afetarão o cronograma geral do projeto.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (53,'- Manter-se atualizado sobre mudanças nas regulamentações locais e ajuste os planos conforme necessário para garantir a conformidade contínua');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (54,'- Realizar uma Avaliação de Impacto Ambiental (AIA), abrangendo os impactos sociais e ambientais do projeto, incluindo os efeitos cumulativos, antes de iniciar a construção');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (55,'- Elaborar um Plano de Gestão Ambiental (PGA) com o objetivo de prevenir, atenuar ou compensar os impactos adversos e valorizar os benefícios socioambientais');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (56,'- Preparar um Plano Básico Ambiental (PBA) ou Plano de Controle Ambiental (PCA) para orientar, monitorar e controlar as ações propostas no PGA');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (57,'- Realizar estudos hidrogeológicos abrangentes e detalhados durante a fase preliminar do projeto para identificar com precisão as condições do lençol freático, as características geológicas e os potenciais desafios relacionados à água subterrânea');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (58,'- Estabelecer planos de monitoramento contínuo das condições hidrogeológicas no local durante toda a execução do projeto');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (59,'- Consultar especialistas em hidrogeologia e geotecnia para obter orientação especializada sobre como lidar com as condições identificadas.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (60,'- Treinar as equipes de operadores com a utilização de simuladores e campos de prova.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (61,'- Investir em tecnologia de projetos e em metodologia de modelagem de informações de construção (BIM)');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (62,'- Garantir que as equipes em treinamento recebam a capacitação adequada, de acordo com as exigências do projeto');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (63,'- Designar equipes de supervisores qualificados e independentes para monitorar a execução do projeto e identificar riscos potenciais de retrabalho.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (64,'- Realizar auditorias periódicas para revisar o andamento do projeto, identificar possíveis desvios e garantir a conformidade com as especificações técnicas e padrões normativos');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (65,'- Revisar e atualizar constantemente as normas técnicas e regulamentos aplicáveis, atualizando periodicamente o projeto e ajustando-o de acordo com as necessidades.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (66,'- Garantir que a equipe de projeto, construção e supervisão seja composta por profissionais devidamente qualificados e experientes');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (67,'- Realizar treinamento da equipe em Saúde e Segurança doTrabalho e melhores práticas de construção para todos os funcionários envolvidos na obra');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (68,'- Gerenciar eficazmente os prazos e recursos, levando em consideração os desafios potenciais, como condições climáticas adversas, falta de insumos e prazos exíguos');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (69,'- Realizar treinamento contínuo para a equipe sobre temas relevantes como legislação aplicável, ética, e gestão de contratos');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (70,'- Assegurar que todos os termos e condições do contrato/instrumento de parceria sejam claros e compreendidos por todas as partes envolvidas.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (71,'- Desenvolver e implementar planos de mitigação para minimizar os impactos ambientais dos projetos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (72,'- Desenvolver e implementar planos de mitigação para minimizar os impactos ambientais dos projetos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (73,'- Utilizar técnicas de gestão de projetos para monitorar a execução dos contratos, garantindo que os prazos, custos e qualidade sejam cumpridos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (74,'- Adotar redação clara e precisa das cláusulas contratuais, incluindo mecanismos de resolução de disputas e procedimentos para aditivos contratuais.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (75,'- Realizar capacitação contínua da equipe envolvida em licitações e contratos sobre as melhores práticas e conformidade legal');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (76,'- Estabelecer programas de compliance que incluam treinamento, monitoramento e canais de denúncia para práticas ilegais ou antiéticas');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (77,'- Realizar auditorias periódicas para verificar a conformidade legal e identificar oportunidades de melhoria');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (78,'- Adotar os modelos de editais propostos pela AGU.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (79,'- Implementar sistemas de monitoramento e controle rigorosos para acompanhar o progresso da obra e identificar problemas rapidamente');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (80,'- Prever planos de contingência para lidar com imprevistos e mudanças nas condições');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (81,'- Adotar práticas de gestão ambiental para minimizar impactos e cumprir com os requisitos legais.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (82,'- Realizar um planejamento detalhado e abrangente, considerando todos os aspectos do projeto');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (83,'- Instaurar processo administrativo destinado à apuração de fato lesivo ao erário, bem como à responsabilização dos agentes envolvidos');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (84,'- Nenhuma');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (85,'- Criar um Plano de Contingëncia para crise.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (86,'- Instalar um gabinete de crise');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (87,'- Informar às Partes Interessadas sobre o evento do risco ocorrido');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (88,'- Informar ao Órgão Concedente sobre o evento do risco ocorrido');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (89,'- Informar ao Escalão Superior e ao CMilA sobre o evento do risco ocorrido');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (91,'- Informar ao escalão superior sobre o evento de risco ocorrido');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (92,'- Notificar formalmente a Contratada sobre o atraso na obra/aquisição');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (93,'- Notificar formalmente o Concedente sobre o atraso na obra');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (94,'- Notificar formalmente a Autoridade Competente sobre a ocorrência');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (95,'- Elaborar, quando houver mudanças no projeto, um Termo de Solicitação e Parecer de Mudanças.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (96,'- Compatibilizar os Projetos Básicos das Disciplinas de Arquitetura e Engenharia antes de desenvolver os Projetos Executivos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (97,'- Acompanhar junto à A/2 do DEC e ao EME a formulação e descentralização do PDRAENG.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (98,'- Formular o planejamento de descentralização de créditos em A-1 com a definição clara dos limites do Programa/Projeto');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (99,'- Ter um plano de rebalanceamento de recursos no Programa, com prioridades definidas entre os projetos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (100,'- Propor ajustes no cronograma de desembolso dos projetos, a fim de reduzir o impacto dos contingenciamentos, tendo como 1ª Laç  prolongar o cronograma de desembolso');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (101,'- Manter informados os Gerentes de Projeto e Partes Interessadas sobre os eventuais cortes/contingenciamentos, bem como as medidas propostas de rebalanceamento do programa');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (102,'- Elaborar um Plano de Comunicação, com as informações estratégicas do Programa/Projeto');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (103,'- Elaborar um Plano de Comunicação do Programa ou Projeto');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (104,'- Elaborar um Mapa de Benefícios dos Projetos');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (105,'- Divulgar o Mapa de Benefícios dos Projetos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (106,'- Estimar os custos dos novos projetos');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (107,'- Solicitar recursos adicionais para fazer frente aos custos dos novos projetos');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (108,'- Realizar a capacitação de G Pgm para possíveis futuros integrantes');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (109,'- Manter uma memória documental atualizada e organizada do programa');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (110,'- Criar condições favoráveis à retenção dos talentos existentes');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (111,'- Iniciar o processo de convocação de PTTC');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (112,'- Ter um plano de recompletamento de PTTC especialista em G Pgm para o PENSE');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (113,'- Desenvolver um plano de treinamento de novo Gerente/Supervisor/Analista do PENSE');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (114,'- Estabelecer contato prévio com os Gpt E, a fim de verificar se as informações recebidas das OME estão de acordo com a consciência situacional das Operações de Engenharia.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (115,'- Acompanhar a Dtz de Iniciação e o EVTEA desde a confecção da minuta até a assinatura.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (116,'- Corrigir a Dtz de iniciação e os EVTEA desde a confecção da minuta até a assinatura.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (117,'- Acompanhar as principais obras usando a FIO e o OPUS.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (118,'- Verificar se o plano de contingência (tratamento do risco) foi aplicado corretamente e informar ao DEC e à autoridade patrocinadora.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (119,'- Acompanhar a elaboração do Termo de Recebimento e Entrega de Obra (TEREO) pelo OPUS');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (120,'- Verificar se as correções do TEREO no OPUS foram realizadas acertadamente.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (121,'- Nenhuma');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (122,'- Implemetar o Plano de Integridade o SEEx');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (123,'- Elaborar e disseminar políticas de conformidade, códigos de conduta e diretrizes de valores éticos que orientem as ações dos militares, civis e parceiros no âmbito do SEEx');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (124,'- Realizar o monitoramento das atividades por meio de controles internos rigorosos e auditorias periódicas, visando identificar e corrigir possíveis desvios no âmbito do SEEx.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (125,'- Estabelecer a segregação de funções nos processos críticos de tomada de decisão, contratação, aquisição e elaboração de aditivos contratuais.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (126,'- Promover o rodízio periódico de pessoal nas funções críticas que envolvam tomada de decisão, contratação, aquisição e elaboração de aditivos contratuais.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (127,'- Desenvolver um plano de capacitação em integridade, focando na responsabilidade individual, procedimentos internos e legislação pertinente: Lei Anticorrupção (12.846/2013), Lei de Conflito de Interesses (12.813/2013) e Decreto 8.420/2015, entre outras.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (128,'- Conduzir uma investigação detalhada mediante a instauração de um processo administrativo, assegurando o direito à ampla defesa e ao contraditório, com o objetivo de apurar os fatos, identificar as causas e coletar evidências relevantes ao incidente.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (129,'- Aplicar sanções disciplinares aos agentes da administração e a terceiros envolvidos, em conformidade com a legislação vigente, assegurando os direitos à ampla defesa e ao contraditório, a fim de reforçar a cultura de responsabilidade e compliance.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (130,'- Implementar um sistema de monitoramento para acompanhar a eficácia das medidas corretivas e preventivas adotadas, avaliando se o risco foi mitigado.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (131,'- Revisar e atualizar políticas, procedimentos e controles internos que tenham eventualmente falhado ou contribuído para a ocorrência do risco, assegurando a implementação de melhorias e medidas preventivas para evitar recorrências futuras.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (132,'- Criar ou atualizar planos de contingência que permitam à organização responder rapidamente a futuros incidentes relacionados à integridade.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (133,'- Conduzir uma análise pós-incidente para identificar o impacto do evento e as lições aprendidas, documentando-as para aprimorar futuras estratégias de prevenção e resposta.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (134,'- Conduzir um processo formal de análise do perfil profissiográfico do agente público, com o objetivo de avaliar a compatibilidade com a ocupação de cargo ou o desempenho de função que seja sensível à integridade da instituição.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (135,'- Conduzir um processo de verificação e confirmação, por meio de evidências formais, do cumprimento das disposições estabelecidas no plano de integridade do SEEx.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (136,'- Criar canais seguros e anônimos (ouvidoria) para que os agentes públicos e stakeholders possam reportar suspeitas de conflito de interesse sem receio de retaliações.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (137,'- Implementar procedimentos de revisão para contratos e processos licitatórios, garantindo que não haja vínculos pessoais ou financeiros entre os envolvidos e as partes contratadas.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (138,'- Garantir a transparência na divulgação de informações relevantes ao público, permitindo um escrutínio externo que possa ajudar a identificar potenciais conflitos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (139,'- Revisar e atualizar regularmente os procedimentos e políticas relacionadas ao gerenciamento de conflitos de interesse, adaptando-os às novas realidades e riscos identificados.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (140,'- Aplicar uma política de rotatividade de pessoal em cargos sensíveis para reduzir a possibilidade de relações pessoais que possam influenciar decisões.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (141,'- Implementar mecanismos de monitoramento contínuo e auditorias periódicas, acompanhados da produção de evidências, visando identificar e avaliar situações de conflito de interesse, garantindo a atualização e a precisão das informações.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (142,'- Assegurar que todos os projetos de engenharia e demais documentos técnicos tenham sido entregues pelo Concedente, completos e devidamente revisados antes do início da execução das obras.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (143,'- Proceder à realização de análises geológicas, climáticas e ambientais detalhadas, com o objetivo de antecipar possíveis problemas técnicos e, assim, prevenir interrupções no andamento das atividades');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (144,'- Assegurar que a força de trabalho alocada para a execução do plano de trabalho seja dimensionada de maneira adequada, tanto em termos de quantidade quanto de capacidade técnica, de forma a garantir o cumprimento das metas estabelecidas.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (145,'- Na hipótese de que a obra exija habilidades específicas, buscar equipes qualificadas no Sistema de Engenharia do Exército para evitar falhas técnicas.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (146,'- Antecipar a necessidade de aditivos ou revisões de projetos e submetê-los ao Concedente com a devida antecedência, garantindo a tramitação e aprovação dos processos sem atraso.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (147,'- Estabelecer um plano de contingência operacional com pontos de controle mensais, semestrais e anuais, a fim de fornecer consciência situacional adequada aos três escalões de decisão: Gpt E enquadrante, Diretoria Enquadrante e DEC.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (148,'- Elaborar relatórios detalhados e periódicos a serem encaminhados ao Concedente, com informações atualizadas sobre o andamento das obras ou serviços, bem como eventuais dificuldades encontradas, para que possam ser resolvidas de forma conjunta.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (149,'- Elaborar um plano de trabalho que reflita de maneira fidedigna a capacidade técnica e operacional da Organização Militar (OM) executante, contemplando eventuais atrasos e imprevistos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (150,'- Realizar uma revisão minuciosa do planejamento da obra, promovendo os ajustes necessários no cronograma, nos recursos e nas atividades, de modo a refletir a nova realidade do plano de trabalho.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (151,'- Incluir na revisão as formalizações necessárias e a análise dos projetos em fase de obra (RPFO), bem como a implementação de aditivos ao plano de trabalho.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (152,'- Identificar e implementar ações corretivas para eliminar as falhas que originaram o risco, visando garantir o cumprimento das metas previamente estabelecidas.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (153,'- Promover o reforço da força de trabalho mediante a mobilização de efetivos de outras Organizações Militares do Sistema de Engenharia do Exército (SEEx).');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (154,'- Solicitar apoio externo de força de trabalho, quando necessário, para atividades não específicas de Engenharia no SEEx, incluindo serviços de balizamento, segurança, suporte logístico e manutenção de equipamentos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (155,'- Identificar novos fornecedores ou parceiros logísticos para suprir demandas de insumos e equipamentos que impactem o andamento das obras, após o esgotamento das medidas administrativas aplicáveis à resolução dos problemas detectados.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (156,'- Desenvolver e implementar planos de contingência específicos para os diferentes tipos de riscos identificados, garantindo a disponibilidade imediata de estratégias para resposta a ocorrências adversas.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (157,'- Implementar junto ao Concedente procedimentos internos mais rápidos e eficientes para analisar e aprovar eventuais aditivos contratuais, reajustes ou revisões de projeto necessários para a continuidade da execução.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (158,'- Realizar avaliações contínuas dos riscos técnicos, financeiros e operacionais envolvidos na execução do instrumento de parceria, atuando proativamente para mitigá-los.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (159,'- Antes da celebração do instrumento de parceria, realizar, em conjunto com o órgão parceiro, uma análise rigorosa da capacidade técnica, operacional e financeira da(s) OM(s) executante(s) para verificar se possui condições de cumprir o objeto.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (160,'- Garantir, antes do início da obra, que todos os projetos de engenharia e documentos técnicos, incluindo licenças, autorizações e alvarás, tenham sido entregues pelo Órgão Concedente, completos e revisados, evitando ajustes durante a execução.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (161,'- Garantir, antes do início da obra, que todos os projetos de engenharia e documentos técnicos, incluindo licenças, autorizações e alvarás, tenham sido entregues pelo Órgão Concedente, completos e revisados, evitando ajustes durante a execução.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (162,'- Elaborar um Plano de Trabalho compatível com a capacidade técnica e operacional da Organização Militar executante, considerando, em sua reserva gerencial, a possibilidade de atrasos e imprevistos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (163,'- Elaborar o Plano de Trabalho segmentado em etapas, com entregas definidas e cronogramas físico-financeiros individuais limitados a 180 dias, viabilizando o controle semestral do progresso do empreendimento e possibilitando ajustes quando necessários.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (164,'- Ao final de cada etapa, torna-se obrigatória a apresentação da Prestação de Contas Parcial (PCP) ao Concedente, detalhando as atividades executadas.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (165,'- Os custos relacionados à administração local, instalação e manutenção do canteiro de obras, além da mobilização e desmobilização, devem ser limitados anualmente a um máximo de 8% do custo direto das etapas do ano, conforme o Acórdão TCU 2.622/2013.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (166,'- A limitação desses custos visa prevenir a ocorrência de sobrepreço, especialmente em situações que demandem supressões de serviços previstas no Plano de Trabalho original.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (167,'- Assegurar que a força de trabalho alocada para a execução do plano de trabalho seja dimensionada de maneira adequada, tanto em termos de quantidade quanto de capacidade técnica, de forma a garantir o cumprimento das metas estabelecidas.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (168,'- Antecipar a necessidade de aditivos ou revisões de projetos e submetê-los ao Concedente com a devida antecedência, garantindo a tramitação e aprovação dos processos sem atraso.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (169,'- Implementar procedimentos internos que assegurem a tramitação ágil de documentos e aprovações, de modo a evitar morosidade administrativa decorrente da burocracia interna.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (170,'- Estabelecer um plano de contingência operacional com pontos de controle mensais, semestrais e anuais, a fim de fornecer consciência situacional adequada aos três escalões de decisão: Gpt E enquadrante, Diretoria enquadrante e DEC.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (171,'- Elaborar relatórios detalhados e periódicos para o Concedente, contendo informações atualizadas sobre o andamento das obras ou serviços e eventuais dificuldades encontradas, permitindo a resolução conjunta e assegurando a cooperação entre as partes.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (172,'- Elaborar um plano de contingência logístico para lidar com eventuais atrasos ou falhas na entrega de insumos ou equipamentos, assegurando a existência de alternativas de fornecimento.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (173,'- Caso a obra exija habilidades específicas, buscar equipes qualificadas no SEEx. Na ausência de profissionais disponíveis, proceder à contratação de equipes terceirizadas para evitar eventuais falhas técnicas.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (174,'- Revisar o Plano de Trabalho vigente, com o objetivo de ajustá-lo aos prazos de execução disponíveis, considerando a possibilidade de redução do escopo, se necessário, para assegurar o cumprimento do Instrumento de Parceria.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (175,'- Verificar  semanalmente se o Plano de Movimentações, proposto pelo DEC, está sendo efetivado');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (176,'- Proceder à revisão integral do processo, aplicando uma metodologia de verificação por meio de check-list para assegurar a presença obrigatória de todos os elementos essenciais em cada peça processual.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (177,'- Solicitar via DIEx à DCEM a movimentação de concluintes das Escolas de Formação, Aperfeiçoamento e Altos Estudos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (178,'- Desenvolver e implementar uma política de tolerância zero ao assédio moral, especificando condutas caracterizadoras e respectivas sanções, comunicando-a formalmente a todos os integrantes do SEEx e incorporando-a ao código de ética organizacional.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (179,'- Promover treinamentos periódicos sobre assédio moral para todos os agentes públicos e lideranças, contemplando sua definição, formas de identificação e prevenção.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (180,'- Criar canais de ouvidoria confidenciais e seguros, onde os agentes públicos possam relatar incidentes de assédio sem receio de retaliação.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (181,'- Promover uma cultura de transparência, respeito e valorização da diversidade e da inclusão, reforçando esses valores em todos os níveis da organização.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (182,'- Conscientizar as lideranças para identificar comportamentos abusivos e agir de maneira rápida e adequada ao notar atitudes de assédio ou clima hostil.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (183,'- Estabelecer processo disciplinar objetivo para casos comprovados de assédio moral, com aplicação justa e transparente, detalhado na política institucional e de amplo conhecimento de todos os integrantes.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (184,'- Garantir que as punições sejam consistentes e proporcionais, para que os agentes públicos entendam as consequências do assédio.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (185,'- Realizar avaliações regulares para identificar áreas da organizaçãio mais vulneráveis ao assédio moral e implementar melhorias.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (186,'- Incentivar que os integrantes da organização compartilhem feedbacks sobre suas experiências no ambiente de trabalho, utilizando ferramentas como pesquisas anônimas ou caixas de sugestões.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (187,'- Instaurar Processo Administrativo para apuração das denúncias, assegurando a confidencialidade e a integridade dos envolvidos, bem como o direito ao contraditório e à ampla defesa.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (188,'- Utilizar uma equipe de investigação qualificada e independente, que possa garantir uma análise justa e evitar qualquer tipo de viés.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (189,'- Prover apoio psicológico e orientação profissional para a vítima, por meio de atendimento especializado, como psicólogos ou assistentes sociais.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (190,'- Garantir a proteção contra retaliação ao colaborador que denunciou o assédio, assegurando que ele possa continuar suas atividades sem pressões adicionais.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (191,'- Adotar sanções disciplinares proporcionais e adequadas aos autores de assédio, conforme a gravidade e as normas internas previstas.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (192,'- Documentar as ações tomadas, assegurando que o processo siga o código de conduta e as políticas organizacionais.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (193,'- Reavaliar e, se necessário, reformular as políticas de prevenção ao assédio moral para reforçar as medidas de proteção.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (194,'- Promover treinamentos de conscientização adicionais para todos os colaboradores, especialmente para as lideranças, reforçando a postura de tolerância zero ao assédio.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (195,'- Comunicar aos integrantes da organização, de forma ampla, o compromisso institucional no enfrentamento ao assédio, resguardando a privacidade dos envolvidos ao omitir detalhes específicos do caso.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (196,'- Garantir que a comunicação interna seja clara quanto às medidas adotadas e à importância de um ambiente de trabalho seguro, saldável e respeitoso.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (197,'- Acompanhar a situação do colaborador afetado e do ambiente onde ocorreu o assédio, avaliando se houve melhora no clima organizacional e na segurança psicológica do grupo.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (198,'- Fortalecer a cultura de respeito e ética, promovendo eventos ou programas de conscientização sobre a importância da integridade e do respeito mútuo.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (199,'- Incentivar uma liderança responsável e empática, comprometida em identificar e agir prontamente em situações que possam gerar assédio.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (200,'- Informar ao fornecedor que será aberto um Processo Administrativo para apuração de responsabilidades e possíveis sanções administrativas.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (201,'- Verificar com o fornecedor quais os problemas para a não entrega do material.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (202,'- Verificar com o fornecedor a possibilidade de novo prazo, enfatizando a necessidade do cumprimento deste.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (203,'- Aplicação de sãções administrativas ao fornecedor após o transcurso do prazo estabelecido e a conclusão do PA.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (204,'- Anular o empenho respectivo.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (205,'- Após a conclusão do PA, convocar a 2ª colocada no processo licitatório.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (206,'- Coordenar com a CEBW, em A-1 as ações necessárias para as aquisições, verificando a documentação necessária e os prazos ajustados.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (207,'- Elaborar e dar entrada na CEBW com o PCI e QI, na data mais cedo possível, conforme o calendário da SEF.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (209,'- Buscar realizar a externação do recurso o mais cedo possivel, de acordo com o calendário estabelecido pela SEF');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (210,'- Iniciar um processo emergencial de aquisição internacional, para substituir o processo fracassado.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (211,'- Solicitar à CEBW, em caráter excepcional, a análise e aprovação de QI de emergência.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (212,'- Verificar, se for o caso, a necesidade de complementação de recursos para o novo processo licitatório.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (213,'- Realizar reuniões bilaterais para verificar a disponibilidade de recursos nos Prg EE');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (214,'- Apresentar na reunião do  CGOM a consolidação das reuniões bilaterias com os Prg EE');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (215,'- Realizar reuniões com o A/4 Gab Cmt Ex e 6ª SCh para verificar as possíveis emendas parlamentares a serem destinadas ao DEC');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (216,'- Realizar reuniões com a DOM a fim de verificar a viabilidade das obras propostas nos PRAENG e nas propostas de Emenda Parlamentar');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (217,'- Aprovar os PDRAENG no 1º semestre, permitindo que os processos de licitações em A-1 se iniciem o mais cedo possível.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (218,'- Aprovar os PDRAENG por partes (edições), considerando valores de série histórica da LOA como primeiro limite de recursos orçamentários.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (219,'- Realizar reuniões bilaterais extraordinárias com vistas a responder a eventuais cortes e contingenciamentos de recursos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (220,'- Proposta de nivelamento de recursos na AO para buscar um equilíbrio na execução do PDRAENG');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (221,'- Readequação das metas físicas (atividades) para os novos limites orçamentários.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (222,'- Realizar um aditivo aos PDRAENG com as metas físicas adequadas.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (223,'- Verificar diariamente se o Power BI está operando normalmente');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (224,'- Acionar o profissional de TI especializado em Power BI');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (225,'- Reiniciar o Power BI e realizar as atualizações necessárias');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (226,'- Capacitar e treinar profissionais em elaboração de projetos de Engenharia e Arquitetura, utilizando ferramentas e metodologia Buildin Information Modeling (BIM)');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (227,'- Realizar compatibilização dos projetos em ferramenta BIM adequada, minimizando erros e interferências.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (228,'- Capacitar e treinar profissionais em planejamento, controle e orçamentação de projetos, utilizando ferramentas BIM.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (229,'- Levar em consideração nos projetos do SEEx os requisitos de sustentabilidade obrigatórios e desejáveis.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (230,'- Solicitar aos Gpt E que realizem uma auditoria das informações acerca das operações de engenharia em curso, antes de serem enviadas ao DEC.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (231,'- Recomendar que as OME realizem o registro fotográfiuco das operações, incluindo na foto os dados de localização e data/hora.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (232,'- Caso seja necessário repassar alguma informação ao escalão superior ao SEEx, validar o dado com a fonte que o produziu.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (233,'- Elaborar e divulgar no SOM um check-list de informações a serem lançadas no EVTEA a fim de padrozinar procedimentos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (234,'- Recomendar que as informações lançadas no EVTEA sejam referenciadas às normas locais aplicáveis, tais como o Plano Diretor Municipal, códigos municipais, normas das concessionárias de serviços, e regulamentações ambientais municipais e/ou estaduais.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (235,'- Recomendar que os EVTEA produzidos pelas OME sejam analisados pela Seção Técnica do Gpt E enquadrante,  antes de serem encaminhados ao DEC.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (236,'- Estabelecer comunicação direta com a fonte da informação para corrigir eventuais dados e assegurar uma consciência situacional precisa e confiável.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (237,'- Estabelecer comunicação direta com a fonte da informação para corrigir eventuais dados e assegurar uma consciência situacional precisa e confiável.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (238,'- Criar e implementar procedimento padrão de análise de EVTEA na DOM, com parâmetros claros de análise e aprovação.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (239,'- Devolver à OME responsável, via sistema OPUS, os EVTEA que contenham informações incompletas ou possivelmente incorretas.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (240,'- Implementar no sistema OPUS um subsistema de protocolo e armazenamento para os EVTEA.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (241,'- Restituir o processo ao demandante, solicitando as correções necessárias, informações complementares ou novos esclarecimentos pertinentes à demanda.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (242,'- Efetuar as correções e adicionar as informações e esclarecimentos necessários ao processo de aquisição de material ou contratação de serviço, visando possibilitar a continuidade do processo licitatório.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (243,'- Realizar o acompanhamento quinzenal da execução dos projetos de Engenharia e Arquitetura, com a presença da equipe de projetos e uso de ferramentas BIM, promovendo a compatibilização entre as disciplinas para reduzir erros de coordenação e conflitos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (244,'- Acompanhar o histórico de liquidações de recursos da obra, utilizando a ferramenta de BI da A/2, para projetar as liquidações futuras e assegurar a disponibilidade de recursos suficientes, evitando a paralisação por falta de orçamento.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (245,'- Monitorar as não-conformidades identificadas nas auditorias ambientais realizadas pela própria OM, com o objetivo de direcionar as ações necessárias para garantir a conformidade com os requisitos ambientais mínimos exigidos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (246,'- Realizar o acompanhamento das ações previstas nos planos de ação das OM que não estejam atendendo aos requisitos mínimos de conformidade ambiental, efetuando as recomendações necessárias diretamente no SIGPIMA.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (247,'- Acompanhar o andamento dos Processos Administrativos relacionados a atrasos ou paralisações de obras, a fim de avaliar a viabilidade de retomada da obra com base no contrato vigente ou por meio da contratação do remanescente.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (248,'- Caso seja necessária a contratação do remanescente da obra devido à rescisão contratual da empresa contratada, verificar se a segunda colocada possui condições de assumir a execução da obra por meio de um novo contrato.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (249,'- Verificar a disponibilidade orçamentária para a retomada das obras paralisadas, submetendo a análise ao CGOM para aprovação.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (250,'- As CRO/SRO deverão monitorar os processos de TEREO em aberto, incluindo os que não são de sua responsabilidade, comunicando ao Gpt E/RM enquadrante para que sejam adotadas as providências necessárias.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (251,'- O GptE/RM enquadrante deverá informar mensalmente à DOM as obras concluídas que ainda não possuem TEREO.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (252,'- A SG3/DOM deverá implementar uma funcionalidade no OPUS para monitorar as obras concluídas que ainda não possuem TEREO.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (253,'- A APG/DOM será responsável, mensalmente, por consolidar as informações sobre as obras concluídas que ainda não possuem TEREO e comunicar ao Diretor de Obras Militares.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (254,'- O Diretor de Obras Militares solicitará aos GptE/RM responsáveis a atualização da elaboração do TEREO para as obras concluídas, quando o prazo ultrapassar 90 dias sem a emissão do referido termo.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (255,'- Elaborar uma Nota à Imprensa e comunicar ao público interno sobre o ocorrido, com o objetivo de esclarecer os fatos, mitigar os impactos e informar sobre as medidas subsequentes ou necessárias.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (256,'- Revisar o Plano de Comunicação Estratégica, com o objetivo de identificar possíveis falhas e propor melhorias.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (257,'- Informar ao CCOMSEX sobre o evento de comunicação estratégica malsucedido, por meio da FIPIS (RESISCOMSEX).');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (258,'- Priorizar o uso de emendas parlamentares para a implantação de usinas fotovoltaicas modularizadas, com projetos já elaborados pela DPE e aprovados na DOM.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (259,'- Coordenar com o Gab Cmt Ex, Asse Parl/Cmil A, Gpt E, DEC e Diretorias as atividades a serem incluídas no portfólio de Emendas Parlamentares em A-1.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (260,'- Considerar para contratação por emendas apenas as obras que já possuam projetos prontos em A-1 e aprovados na DOM.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (261,'- Estabelecer planejamento específico entre o DEC e o Gab Cmt Ex para a gestão das atividade custeadas por emendas parlamentares, com acompanhamento e execução operacionalizados em painel dedicado no Power BI.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (262,'- Caso o processo licitatório seja malsucedido, readequar o objeto da Emenda Parlamentar para uma atividade com processo de contratação simplificado.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (263,'- Manter comunicação contínua com o Parlamentar ou bancada responsável pela Emenda, visando facilitar eventuais ajustes necessários.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (264,'- Restituir o crédito ao Parlamentar/bancada para alocação em outra atividade, dentro do prazo estabelecido.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (265,'- Empregar esforços para evitar a inscrição do recurso em Restos a Pagar.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (266,'- Avaliar a viabilidade da execução do objeto da emenda por meio de execução direta.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (267,'- Realizar corretamente os estudos dos documentos preliminares.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (268,'- Implementar um plano de sinalização e controle de tráfego para minimizar riscos de acidentes durante a obra.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (269,'- Realizar auditorias ambientais periódicas para garantir conformidade com as normas ambientais e reduzir impactos ecológicos.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (270,'- Desenvolver e implementar um plano de contingência para abastecimento de insumos críticos, garantindo estoques estratégicos');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (271,'- Elaborar um plano de resposta a emergências para lidar com eventos como desmoronamentos, enchentes e acidentes de trabalho');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (272,'- Utilizar drones para inspeção das obras, garantindo mais precisão na identificação de falhas estruturais e de segurança');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (273,'- Realizar oficinas técnicas e reuniões do SOM para capacitar o pessoal. Cobrar a documentação da obra. Notificar a empresa quando do descumprimento de alguma cláusula contratual.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (274,'- O Aux SG2 solicita ao Mil Mvt que remeta urgente o Diex de opção.');
INSERT INTO "acoes_a_executar" ("codacexe", "acoes") VALUES (275,'- Definir claramente o objetivo do evento, o público-alvo, a mensagem principal, os porta-vozes responsáveis, do formato, o cronograma e os resultados esperados.');
