INSERT INTO "analise_swot" ("codigo", "processo", "forcas", "oportunidades", "fraquezas", "ameacas", "analista", "data", "o_processo_tem_alinhamento_com_os_objetivos_da_organizacao", "normas_e_regulamentos_utilizados", "objetivos_do_processo", "responsavel_pela_analise", "imagem") VALUES ('0101DECA3','01DECA3','- Processos cadastrados\r\n- Equipe instruída\r\n- Experiência em processos semelhantes','- Novas capacidades no SEEx serão agregadas','- Informaçãoes que não expressam a realidade\r\n- Atraso na atualização das informações\r\n- Recebimento de informações equivocadas','- Dificuldades no recebimento das informações pelos Gpt E','01DECA3','2024-06-17 00:00:00',FALSE,2,2,NULL,NULL);
