INSERT INTO "analise_swot" ("codigo", "processo", "forcas", "oportunidades", "fraquezas", "ameacas", "analista", "data", "o_processo_tem_alinhamento_com_os_objetivos_da_organizacao", "normas_e_regulamentos_utilizados", "objetivos_do_processo", "responsavel_pela_analise", "imagem") VALUES ('0101DECA6','01DECA6','- Processos devidamente cadastrados\r\n- Equipe instruída e motivada\r\n- Treinamento em Gestão de Processos','- Novas capacidades da A6/DEC serão agregadas\r\n- Treinamento da equipe \r\n- Atualização costante','- Primeira vez que será gerenciado o risco\r\n- Documentação faltante no processo\r\n- Organização processual em desconformidade','- Dificuldades na tramitação dos processos e documentos\r\n- Falta de conhecimento sobre o processo','01DECA6','2024-06-18 00:00:00',FALSE,4,4,NULL,NULL);
INSERT INTO "analise_swot" ("codigo", "processo", "forcas", "oportunidades", "fraquezas", "ameacas", "analista", "data", "o_processo_tem_alinhamento_com_os_objetivos_da_organizacao", "normas_e_regulamentos_utilizados", "objetivos_do_processo", "responsavel_pela_analise", "imagem") VALUES ('0101DECAEPG','01DECAEPG','1. A Capacitação contínua das Equipes de Governança e Gestão (EG²) fortalece o controle interno e a gestão da conformidade, favorecendo o tratamento adequado dos riscos à integridade.\r\n\r\n2. O Domínio normativo das EG² assegura aderência às normas legais, com ênfase em integridade, ética e responsabilização na Administração Pública.\r\n\r\n3 - A estrutura colegiada das EG², coordenada pela AEPG/DEC, garante processos formais e sistemáticos de gestão de riscos e fortalecimento da integridade institucional.\r\n\r\n4 - A promoção periódica de Instruções de Quadros fortalece a cultura de integridade, alinha práticas à boa governança e aumenta a resiliência institucional frente a riscos éticos e legais.\r\n\r\n5. A valorização dos princípios militares, a ação de comando em todos os níveis e o espírito de patriotismo e camaradagem fortalecem a cultura organizacional e inibem desvios de conduta na gestão pública militar.','1. O apoio institucional e a priorização conferida pela Alta Administração do DEC ao tema reforçam os pilares da governança, consolidam a cultura de integridade e impulsionam o aperfeiçoamento contínuo da gestão de riscos.\r\n\r\n2. A atuação da AGG/EME como instância técnica e estratégica viabiliza o alinhamento metodológico e o fortalecimento da maturidade institucional na gestão de riscos à integridade.','1. O ineditismo do processo de gestão de riscos à integridade no DEC, instituído em 2024/2025, implica baixa maturidade, ausência de histórico e necessidade de evolução de rotinas e indicadores.\r\n\r\n2. A recente atualização do Plano e Programa de Integridade do Exército em 2024/2025, ainda restringe a consolidação de fluxos, metodologias e instâncias de articulação, impactando a efetividade sistêmica das ações de integridade.','- Não foram verificados','01DECPENSE','2024-10-09 00:00:00',FALSE,5,5,NULL,NULL);
INSERT INTO "analise_swot" ("codigo", "processo", "forcas", "oportunidades", "fraquezas", "ameacas", "analista", "data", "o_processo_tem_alinhamento_com_os_objetivos_da_organizacao", "normas_e_regulamentos_utilizados", "objetivos_do_processo", "responsavel_pela_analise", "imagem") VALUES ('0101DECSALC','01DECSALC','- Equipe instruída\r\n- Experiência em processos semelhantes\r\n- Metodologia interna estabelecida: "Um Empenho para Chamar de Seu"','- Novas capacidades no SEEx serão agregadas\r\n- Apoio de todos os militares do Departamento e Diretorias Subordinadas','- Primeira vez que será gerenciado o risco do processo\r\n- Quantidade de pessoal insuficiente na SALC/DEC','- Dificuldades dos fornecedores em atender aos prazos\r\n- Dificuldade de contato com os fornecedores','01DECGAB','2024-07-02 00:00:00',FALSE,6,6,NULL,NULL);
