INSERT INTO "categorizacao_do_impacto" ("codimp", "impacto", "i", "explicacao") VALUES ('04','Alto',4,'Interrupção de operações, atividades, projetos, programas ou processos da organização, causando impactos de difícil reversão nos objetivos.');
