INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (83,'Não atingimento das metas físicas semestrais estabelecidas no P Trab (detecção no nível da DOC)');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (84,'Índice de Variação de Custo trimestral da obra acima de 1,0 (detecção a cargo do Gpt E)');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (85,'Índice de Variação de Custo semestral da obra acima de 1,0 (detecção a cargo da DOC)');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (86,'Registros em relatórios de fiscalização técnica sobre falhas graves em execução da obra');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (87,'Interrupções frequentes por falhas técnicas ou retrabalhos');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (88,'Atrasos recorrenters na tramitação de aditivos, licenças ou pareceres obrigatórios.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (89,'Ausência de atualizações regulares nos sistemas de controle ou prestação de contas ao Concedente.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (90,'Novos riscos técnicos ou administrativos identificados durante a execução do P Trab');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (91,'Agravamento de riscos já mapeados sem resposta eficaz.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (92,'Quadro técnico reduzido, indisponibilidade de equipamentos ou falhas na logística de suprimentos');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (93,'Ausência de profissionais-chave ou mudanças não previstas na estrutura de execução.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (94,'Falta de retorno do Concedente a solicitações essenciais');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (95,'Falhas de alinhamento entre OM executante e o Escalão Superior');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (96,'Indícios de esgotamento do prazo de execução sem proporcional avanço físico-financeiro');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (97,'Auditorias com constatações de desvios relevantes.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (98,'Requisições ou notificações dos Órgãos de Controle Interno, TCU ou Ministério Público');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (99,'Atrasos superiores aos limites pré-definidos pelo Gpt E e DOC em marcos intermediários ou entregas previstas no cronograma.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (100,'Redução contínua no índice de produtividade das OME executantes');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (101,'Notificação de não-conformidade técnica ou ambiental por parte dos órgãos de fiscalização/controle');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (102,'Recurso insuficiente para a execução total da atividade ou projeto');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (103,'Verificação sistemática das declarações de vínculos externos (ex: DIR – Declaração de Interesses e Relações), cruzando com bases de dados públicas e privadas');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (104,'Acompanhamento por amostragem ou por denúncias de atividades externas indevidas divulgadas publicamente por agentes públicos');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (105,'Execução de auditorias temáticas voltadas para acúmulo de funções, conflitos de interesse e atuação indevida em áreas correlatas');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (106,'Integração de sistemas para identificar registros de atividades externas (ex: CNPJ, INSS, CREA/CRM/OAB, CNIS, Receita Federal, etc.), detectando possíveis incompatibilidades funcionais');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (107,'Utilização de canais internos e externos de denúncia, com classificação de risco, apuração preliminar e rastreabilidade');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (108,'Emissão de relatórios de conformidade funcional por unidade de integridade, controladoria ou comissão de ética, a partir da revisão de designações e nomeações');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (109,'Identificação de padrões e recorrência de denúncias, reclamações ou sanções associadas a atividades incompatíveis com o cargo');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (110,'Inclusão de perguntas sobre envolvimento em outras atividades profissionais, para possível detecção de incompatibilidades');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (111,'Implementação de mecanismos automatizados para indicar potenciais conflitos ou atividades paralelas com base em comportamentos atípicos ou mudanças de rotina funcional');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (112,'Recebimento e tratamento de denúncias relacionadas à intermediação indevida, com garantia de sigilo e proteção ao denunciante');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (113,'Detecção de decisões administrativas com indícios de favorecimento, por meio de análises de padrão e rastreamento de justificativas');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (114,'Acompanhamento de participações públicas do agente em nome de terceiros, mesmo que não oficialmente designado');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (115,'Identificação de possíveis focos de abuso por meio de aumento anormal de pedidos de transferência, licenças por saúde mental ou desligamentos');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (116,'Mecanismos seguros, sigilosos e acessíveis para registro de denúncias ou relatos anônimos sobre condutas abusivas ou antiéticas.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (117,'Realização sistemática de entrevistas estruturadas com servidores transferidos, exonerados ou afastados, buscando identificar indícios de ambiente tóxico ou abusivo');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (118,'Observação e registro de incidentes em eventos internos, como interrupções, humilhações públicas, desrespeito ou retaliação verbal');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (119,'Execução de auditorias com foco em integridade e conflito de interesses, avaliando a conformidade das decisões administrativas, especialmente em processos de contratação e gestão de convênios.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (120,'Cruzamento periódico de dados de servidores com bases da Receita Federal, CNPJ e sistemas internos para identificar vínculos familiares com representantes ou sócios de empresas contratadas ou interessadas.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (121,'Realização de auditorias específicas ou testes de conformidade sobre decisões mediadas, avaliando indícios de parcialidade.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (122,'Cruzamento de decisões administrativas com indicadores de favorecimento, reincidência de partes ou padrões anômalos de julgamento.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (123,'Inclusão de critérios de imparcialidade e conduta ética nas avaliações periódicas de desempenho de líderes e mediadores.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (124,'Monitoramento sistemático de manifestações na ouvidoria, corregedoria ou canais internos sobre tratamento desigual ou autoritário.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (125,'Estabelecimento de regras normativas objetivas, imparciais e transparentes para a tomada de decisões administrativas suscetíveis de gerar benefícios ou prejuízos a indivíduos ou grupos específicos.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (126,'Publicação formal e ampla divulgação dos critérios técnicos, metodologias de pontuação e parâmetros de julgamento adotados, assegurando previsibilidade e igualdade de tratamento.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (127,'Implementação de cadeia decisória com, no mínimo, duas instâncias hierárquicas, visando controle cruzado, revisão fundamentada e mitigação de riscos de arbitrariedade, favorecimento ou uso abusivo da discricionariedade.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (128,'Acompanhamento das movimentações que estão sendo publicadas, analisando os claros previstos e existentes nas OM do SEEx');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (129,'Documentar todos os acontecimento do Contrato\r\n(Verificar: notificação empresa, Diário de Obra, etc)');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (130,'Documentar e controlar por meio de planilha cada passo do processo de abertura dos editais até a homologação do resultado');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (131,'Conferência imediata do DIEx No recebimento.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (132,'Conferência imediata do DIEx no recebimento');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (133,'A DOM informa à RM os Mil Mvt que não enviaram o DIEx de opção.');
INSERT INTO "controles_de_deteccao" ("codcontdetect", "controle_de_detecao") VALUES (134,'Monitoramento, em painel Power BI, da disponibilidade de recursos por OM pagadora, com projeção de saldo suficiente para custear, no mínimo, quatro folhas de pagamento subsequentes.');
