INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (34,'Métricas de desempenho insatisfatórias');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (35,'Feedback negativo das autoridades reguladoras');
