INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (37,'Relatórios de auditorias externas indicando problemas de qualidade');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (38,'Relatos de funcionários, denúncias anônimas ou qualquer outra evidência de má conduta');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (39,'Paralização por manutenção não programada com avaria inesperada do equipamento');
