INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (41,'Auditoria ou inspeção que identifica não conformidades');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (42,'Falta de documentação clara, como contratos e especificações técnicas');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (43,'Ocorrência de acidente de trabalho');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (44,'Indício de que o contrato foi direcionado para um fornecedor específico sem justificativa adequada ou em benefício de interesses privados');
