INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (46,'Indícios de que o valor do edital/contrato está acima do preço de mercado ou dos valores praticados em contratos similares');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (47,'Ausência de fundamentação em normas legais específicas que autorizem a celebração  do contrato');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (48,'Erros formais no processo de contratação, como falhas na publicação de editais, na documentação exigida ou na análise das propostas');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (49,'Contingenciamento/corte de recursos orçamentários superior a 10% do orçamento do projeto/programa');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (50,'Redução do escopo superior a 20%');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (51,'Demanda, por parte da alta administração, de novos projetos para o PENSE, sem o acréscimo de recursos orçamentários equivalentes');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (52,'Desligamento de especialistas em Gerenciamento de Programa no PENSE');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (53,'Fim do tempo máximo de permanência de PTTC na função (10 anos)');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (54,'Envolvimento de agente público em processos decisórios que afetam diretamente seus interesses pessoais');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (55,'Recebimento de presentes, favores ou outros benefícios por agentes públicos, comprometendo sua imparcialidade em processos decisórios');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (56,'Pressão por partes interessadas, como superiores hierárquicos ou grupos externos, para influenciar agentes públicos em decisões administrativas, desconsiderando a imparcialidade');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (57,'Deficiências na supervisão e na governança que resultam em escassa ou inexistente fiscalização de interesses conflitantes em processos críticos, como licitações, contratos, recebimento de bens e serviços, pagamentos e auditorias');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (58,'Detecção de desvios significativos em relação ao cronograma de marcos planejado');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (59,'Ocorrência de atrasos recorrentes e contínuos em várias fases da obra, sem correções realizadas dentro dos prazos adequados');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (60,'Deteccção de falhas técnicas graves ou imprevistos relacionados às estruturas, sistemas ou condições geológicas que impactam o andamento das obras');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (61,'Necessidades de alterações significativas no projeto executivo durante a execução, sem que tenham sido previstas no planejamento original');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (62,'Discrepância entre a execução orçamentária e o planejamento de custos da obra');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (63,'Dificuldades na comunicação ou na troca de informações entre as partes, que resultem em atrasos ou falhas na execução');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (64,'Ausência de feedback a respeito de problemas identificados e reportados ao Concedente com a ação corretiva oportuna');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (65,'Ausência ou deficiência na realização de auditorias técnicas e financeiras ao longo da execução da obra');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (66,'Transferência (reserva ou movimentação) de militares que ocupavam cargos críticos nas OM sem a devida previsão de recompletamento');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (67,'Prática reiterada de conduta abusiva, no ambiente de trabalho, entre pares ou entre superior hierárquico e subordinado, buscando humilhar, desqualificar, ofender ou constranger um indivíduo');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (68,'Denúncia de prática reiterada de conduta abusiva, no ambiente de trabalho, entre pares ou entre superior hierárquico e subordinado, buscando humilhar, desqualificar, ofender ou constranger um indivíduo');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (69,'Admoestação reiterada do superior hierárquico em relação ao subordinado em ambiente coletivo no local de trabalho');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (70,'Projeto Básico da obra proposta por emenda parlamentar não estar concluído em A-1');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (71,'Falta de coordenação entre a Assessoria Parlamentar do C Mil A e o Gab Cmt, EME e DEC');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (72,'Recurso insuficiente para a execução total da obra');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (73,'Incapacidade operacional da CRO/SRO enquadrante para a confecção dos projetos, contratação e fiscalização da obra');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (74,'Análise técnica e jurídica prévia  do Instrumento de Parceria por equipe multidisciplinar (jurídica, técnica e de controle interno) antes da assinatura');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (75,'Checklist padronizado de conformidade documental com os requisitos formais e materiais exigidos por lei e pelos normativos internos da instituição');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (76,'Modelo-padrão de Instrumento de Parceria institucional, constando de minutas previamente validadas pelo jurídico, com cláusulas essenciais predefinidas');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (77,'Capacitação contínua de gestores e analistas, com treinamento periódico sobre elaboração, análise e gestão de instrumentos jurídicos e planos de trabalho');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (78,'Validação prévia do P Trab pelo Gpt E enquadrante, com conferência técnica e orçamentária do plano, com verificação da compatibilidade entre objeto, metas, recursos e capacidade técnico-operacional das OME executantes');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (79,'Consulta prévia à assessoria jurídica e controle interno, com emissão de parecer jurídico obrigatório e parecer técnico de controle interno como condicionantes para avanço da parceria.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (80,'Estabelecimento formal da cadeia de assessoramento e aprovação em todas as etapas do processo decisório, com a devida definição das competências, atribuições, prazos e responsabilidades dos agentes envolvidos.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (81,'Gestão documental e versionamento dos documentos para evitar erros de conteúdo ou assinatura equivocada');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (82,'Aprovação em instância interna e submissão do processo a comitês ou comissões de análise para deliberação antes da assinatura');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (83,'Existência, quando aplicável, dos elementos técnicos do AnteProjeto, aprovado pelo Concedente, conforme OT IBR 06/2016');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (84,'Existência, quando aplicável, de Projeto Básico, aprovado pelo Concedente, com elementos técnicos necessários e suficientes, e com nível de precisão adequado, para caracterizar o objeto do PTrab, conforme OT IBR 001/2006');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (85,'Licenças ambientais regularmente expedidas pelos órgãos competentes, em conformidade com a legislação ambiental vigente');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (86,'Disponibilidade de diagnóstico ambiental e avaliação dos impactos na área de influência da obra, fornecido e aprovado pelo Concedente, com identificação dos respectivos impactos ambientais, bem como das medidas mitigadoras e compensatórias correspondentes');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (87,'Existência de Projeto Executivo, aprovado pelo Concedente, com o detalhamento necessário para garantir a perfeita execução das atividades previstas no PTrab, conforme OT IBR 008/2020');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (88,'Existência de orçamento do objeto da obra, atualizado, aprovado pelo Concedente e compatível com o grau de precisão do projeto, de acordo com a OT - IBR 004/2012');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (89,'Planejamento detalhado, por parte das OME Executantes, sobre as necessidades de pessoal, insumos, equipamentos e produtos, considerando prazos, quantidades e especificações');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (90,'Monitoramento constante do progresso da entrega de insumos e equipamentos, identificando potenciais problemas logísticos de forma precoce');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (91,'Disponibilidade dos Projetos Executivos e demais documentos técnicos, aprovados pelo Concedente, completos e devidamente revisados pelas OME executantees e Gpt E enquadrante');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (92,'Relatório técnico de reconhecimento do local da obra, realizado pela OME executante, com análises geotécnicas e ambientais detalhadas, para validar os dados do projeto e antecipar problemas técnicos que possam comprometer a continuidade das atividades');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (93,'Dimensionamento  da Força de Trabalho de forma adequada, em termos de quantidade de pessoal, capacidade técnica e disponibilidade de equipamentos, a fim de garantir o cumprimento das metas estabelecidas');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (94,'Alocação  da Frota de Equipamentos, conforme dimensionamento realizado, tanto em termos de quantidade quanto de disponibilidade, de forma a garantir o cumprimento das metas estabelecidas');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (95,'Dimensionamento das Equipes de Trabalho de maneira adequada e realista, tanto em termos de quantidade e dispobilidade de equipamentos e força de trabalho, quanto da capacidade técnico-operacional, de forma a garantir o cumprimento das metas estabelecidas');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (96,'Disponibilidade de equipes qualificadas e consultores especializados, caso a obra demande competências técnicas específicas, visando mitigar deficiências na execução');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (97,'Acompanhamento do P Trab de modo a refletir a capacidade técnica e operacional das OME executantes, prevendo e contemplando eventuais atrasos e imprevistos (reserva de contingência)');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (98,'Monitoramento constante do progresso da entrega de insumos e equipamentos, por parte da OME, identificando potenciais problemas logísticos de forma precoce');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (99,'Análise criteriosa, pelo Escalão Superior enquandrante, da capacidade técnico-operacional da(s) OME executante(s), visando verificar a aptidão para cumprir integralmente o objeto pactuado conforme as exigências estabelecidas');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (100,'Mapeamento prévio de processos de controle, para identificação e submissão tempestiva de necessidades de aditivos contratuais ou revisões de projeto em fase de obra (RPFO) ao Concedente, visando assegurar a tramitação e aprovação sem impacto no cronograma');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (101,'Disponibilidade de planos de mitigação ambiental previamente definidos, contendo diretrizes destinadas à minimização dos impactos decorrentes da execução do projeto, em conformidade com os requisitos legais aplicáveis');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (103,'Implementação de processos regulares para elaboração de relatórios detalhados e periódicos ao Concedente, com informações atualizadas sobre o andamento das obras ou serviços e dificuldades encontradas, visando à resolução conjunta');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (104,'Avaliação, pelo Escalão Superior enquadrante, das metas previstas no P Trab, visando aferir a capacidade técnico-operacional das OME executantes em atender o planejamento');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (105,'Planejamento detalhado das necessidades de insumos, equipamentos e pessoal com antecedência, considerando prazos, quantidades e especificações');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (106,'Acompanhamento constante, junto ao Concedente, do status das solicitações de licenças e permissões, garantindo que todos os prazos sejam atendidos e que as ações necessárias sejam oportunas');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (107,'Registros detalhados de todas as comunicações, alterações no escopo, decisões e eventos que possam afetar o cronograma do projeto');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (108,'Realização de estudos hidrogeológicos no local da obra, na fase preliminar do projeto, com o objetivo de identificar as condições do lençol freático, as características geológicas do terreno e os potenciais desafios associados à água subterrânea');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (109,'Elaboração realista do OOG, com base em tabelas oficiais, contemplando custos diretos, indiretos e reserva de contingência, para assegurar previsibilidade financeira e execução adequada  do empreendimento');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (110,'Relatório técnico de reconhecimento das jazidas previstas em projeto, realizado pela OME executante');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (111,'Recurso insuficiente para a execução total da atividade ou projeto');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (112,'Solicitação, por parte da Autoridade Patrocinadora ou Stakeholder Estratégico, da criação de novos projetos ou atividades dentro do Programa.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (113,'Solicitação, por parte da Autoridade Patrocinadora ou Stakeholder Estratégico, de redução da prioridade de Projetos ou Atividades em curso no Programa.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (114,'Implementação de um Código de Ética e Conduta com cláusulas expressas sobre a vedação ao exercício de atividades incompatíveis, incluindo sanções e canais de denúncia.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (115,'Assinatura obrigatória de termo de compromisso por todos os agentes públicos quanto ao conhecimento das normas sobre incompatibilidade de funções e conflito de interesses');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (116,'Realização de treinamentos regulares sobre ética pública, integridade, conflito de interesses, com foco na prevenção e identificação precoce de situações de risco');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (117,'Atuação de auditorias internas e controladorias para fiscalizar a compatibilidade entre funções exercidas e outras atividades declaradas ou verificadas');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (118,'Implantação de controles de acesso sistêmico e operacional que impeçam a concentração indevida de poderes ou a atuação simultânea em áreas potencialmente conflitantes');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (119,'Elaboração e divulgação de normas e orientações sobre acúmulo de cargos, conflito de interesses e atividades incompatíveis, com base na legislação vigente, como a Lei nº 12.813/2013 e o Código de Ética institucional.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (120,'Regulamentação clara e acessível sobre vedação à intermediação de interesses privados, incluindo definição de condutas vedadas.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (121,'Treinamentos regulares sobre integridade, condutas vedadas e responsabilização por intermediação indevida de interesses.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (122,'Assinatura de termos que impeçam o uso de informações privilegiadas para favorecer interesses particulares.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (123,'Procedimento de consulta à Comissão de Ética ou unidade de integridade em casos de dúvidas sobre possíveis conflitos.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (124,'Inclusão de dispositivos específicos que vedem a atuação informal como procurador, consultor ou assessor de entes privados, com sanções administrativas.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (125,'Estabelecimento de norma interna clara, que defina o que constitui assédio moral, sexual e institucional, com exemplos, penalidades e canais de denúncia');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (126,'Inclusão de cláusulas que reforcem o dever de tratamento digno, respeitoso e profissional entre todos os membros da instituição');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (127,'Realização periódica de treinamentos e campanhas educativas sobre relações interpessoais saudáveis e limites éticos de conduta no trabalho');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (128,'Assinatura de termo de responsabilidade por chefias e lideranças, reforçando a tolerância zero a práticas abusivas e seu papel como exemplo');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (129,'Aplicação de pesquisas periódicas e anônimas para identificar sinais de ambiente tóxico ou relações assimétricas e abusivas');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (130,'Adoção de critérios de seleção e promoção que valorizem inteligência emocional, empatia, respeito e capacidade de liderança ética');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (131,'Atuação conjunta e articulada das instâncias de integridade para antecipar situações de risco relacional e agir preventivamente');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (132,'Inserção, nos regulamentos e códigos de conduta, de cláusulas que impeçam a participação do agente público em processos decisórios envolvendo entidades com as quais possuam vínculo familiar até o 3º grau. Cláusula de Impedimento.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (133,'Implementação de política interna de conflito de interesses, baseada na Lei nº 12.813/2013, e promoção de treinamentos periódicos obrigatórios para orientar agentes públicos sobre prevenção, identificação e reporte, reforçando a integridade institucional.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (134,'Implementação de processos decisórios com mais de um agente envolvido, com registro formal das deliberações, reduzindo o risco de decisões unilaterais e individuais.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (135,'Cruzamento periódico de dados de servidores com bases da Receita Federal, CNPJ e sistemas internos para identificar vínculos familiares com representantes ou sócios de empresas contratadas ou interessadas.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (136,'Disponibilização de canal de denúncia interno e externo, com garantia de anonimato e mecanismos de resposta rápida a indícios de favorecimento ou conflito de interesses.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (137,'Execução de auditorias com foco em integridade e conflito de interesses, avaliando a conformidade das decisões administrativas, especialmente em processos de contratação e gestão de convênios.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (138,'Capacitação continuada dos gestores e mediadores em técnicas de mediação, comunicação não violenta, ética e gestão de conflitos');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (139,'\tRegistro formal dos processos de mediação e acesso restrito às decisões, com rastreabilidade e transparência adequada.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (140,'Estruturação de canal de ouvidoria autônomo e sigiloso para denúncias de parcialidade, favorecimento ou condutas inadequadas.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (141,'\tMonitoramento em painel Power BI da disponibilidade de recursos por OM pagadora, com indicação prospectiva de saldo suficiente para suportar, no mínimo, quatro folhas de pagamento subsequentes.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (142,'\tRotatividade de servidores em cargos sensíveis à mediação de conflitos, como medida de mitigação de vícios comportamentais.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (143,'Acompanhamento das publicações das movimentações dos militares do SEEx');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (144,'Capacitação de pessoal.\r\nControle documental da obra.\r\nNotificações');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (145,'Orientar o militar movimentado a respeito dos prazos a serem cumpridos');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (146,'O Aux SG2 informa ao Ch Gab DOM os Mil Mvt que não enviaram o DIEx de opção.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (147,'Verificação antecipada da disponibilidade orçamentária e financeira para suportar o pagamento da folha do PCTD.');
INSERT INTO "controles_preventivos" ("codcontprevent", "controlprevent") VALUES (148,'Estabelecimento de calendário formal para fechamento, conferência, aprovação e pagamento da folha, com definição clara de prazos e responsáveis.');
