INSERT INTO "copia_de_processos_criticos" ("proccrit", "macroprocesso", "processo_critico", "organizacao", "objetivo_processo", "co") VALUES ('02',8,'Projetos Executivos','DPE','Assegurar a elaboração de projetos executivos com qualidade, eficiência, conformidade e segurança jurídica',NULL);
INSERT INTO "copia_de_processos_criticos" ("proccrit", "macroprocesso", "processo_critico", "organizacao", "objetivo_processo", "co") VALUES ('03',2,'Atividades iniciais (EVTEA, Instrumento de Parceria  -TED ou convênio, Plano deTrabalho e OSv)','DOC','Aprimorar a gestão de Instrumentos de Parceria nas Obras de Cooperação',NULL);
INSERT INTO "copia_de_processos_criticos" ("proccrit", "macroprocesso", "processo_critico", "organizacao", "objetivo_processo", "co") VALUES ('04',2,'Acompanhamento físico e financeiro da obra','DOC','Monitorar o avanço físico e financeiro das obras de cooperação, garantindo controle e conformidade',NULL);
INSERT INTO "copia_de_processos_criticos" ("proccrit", "macroprocesso", "processo_critico", "organizacao", "objetivo_processo", "co") VALUES ('05',2,'Entrega da Obra (Termo de Recebimento e Prestação de Contas Final)','DOC','Melhorar o processo de Prestação de Contas dos Instrumentos de Parceria das Obras de Cooperação',NULL);
INSERT INTO "copia_de_processos_criticos" ("proccrit", "macroprocesso", "processo_critico", "organizacao", "objetivo_processo", "co") VALUES ('06',4,'Gerenciamento das Aquisições e Contratos Internacionais','DME','Otimizar a Logística e o Fornecimento do Material de Engenharia em Contratos Internacionais',NULL);
INSERT INTO "copia_de_processos_criticos" ("proccrit", "macroprocesso", "processo_critico", "organizacao", "objetivo_processo", "co") VALUES ('07',4,'Gerenciamento das Aquisições e Contratos Nacionais','DME','Otimizar a Logística e o Fornecimento do  Material de Engenharia em Contratos Nacionais',NULL);
INSERT INTO "copia_de_processos_criticos" ("proccrit", "macroprocesso", "processo_critico", "organizacao", "objetivo_processo", "co") VALUES ('08',4,'Manutenção Preventiva e Corretiva','DME','Otimizar a Logística de Manutenção do Material de Engenharia',NULL);
INSERT INTO "copia_de_processos_criticos" ("proccrit", "macroprocesso", "processo_critico", "organizacao", "objetivo_processo", "co") VALUES ('09',5,'Conformidade Ambiental','DPIMA','Aumentar a Conformidade e Auditoria patrimonial dos imóveis jurisdicionados ao Exército',NULL);
INSERT INTO "copia_de_processos_criticos" ("proccrit", "macroprocesso", "processo_critico", "organizacao", "objetivo_processo", "co") VALUES ('10',5,'Licenciamento Ambiental da Escola de Sargentos do Exército','DPIMA','Viabilizar e acompanhar o licenciamento ambiental da Escola de Sargentos do Exército',NULL);
INSERT INTO "copia_de_processos_criticos" ("proccrit", "macroprocesso", "processo_critico", "organizacao", "objetivo_processo", "co") VALUES ('11',5,'Licenciamento Ambiental do Complexo de Saúde Severiano da Fonseca (CSSF) – Novo HMAB','DPIMA','Viabilizar e acompanhar o licenciamento ambiental do CSSF – Novo HMAB',NULL);
INSERT INTO "copia_de_processos_criticos" ("proccrit", "macroprocesso", "processo_critico", "organizacao", "objetivo_processo", "co") VALUES ('12',6,'Regularização do patrimônio imobiliário','DPIMA','Assegurar a regularização do patrimônio imobiliário, por meio da coordenação dos atos administrativos, técnicos e cartoriais necessários, visando à conformidade dominial, à segurança jurídica e à adequada gestão dos imóveis.',NULL);
INSERT INTO "copia_de_processos_criticos" ("proccrit", "macroprocesso", "processo_critico", "organizacao", "objetivo_processo", "co") VALUES ('13',6,'Manobras Patrimoniais de Interesse do Exército','DPIMA','Conduzir remanejamentos patrimoniais de interesse do Exército com regularidade e segurança jurídica',NULL);
INSERT INTO "copia_de_processos_criticos" ("proccrit", "macroprocesso", "processo_critico", "organizacao", "objetivo_processo", "co") VALUES ('14',7,'Atividades iniciais de Obras Militares (Diretriz de Iniciação, EVTEA e Contratação)','DOM','Assegurar as atividades iniciais das obras militares, com conformidade, viabilidade e segurança jurídica',NULL);
INSERT INTO "copia_de_processos_criticos" ("proccrit", "macroprocesso", "processo_critico", "organizacao", "objetivo_processo", "co") VALUES ('15',7,'Obras militares no prazo','DOM','Assegurar a execução das obras militares no prazo, com eficiência e segurança jurídica',NULL);
INSERT INTO "copia_de_processos_criticos" ("proccrit", "macroprocesso", "processo_critico", "organizacao", "objetivo_processo", "co") VALUES ('16',7,'Entrega da Obra (termo de recebimento e entrega de obra)','DOM','Assegurar a entrega das Obras Militares com conformidade, formalização e segurança jurídica',NULL);
