INSERT INTO "objetivos_dos_processos" ("codobjproc", "codprocesso", "objetivo_processo") VALUES ('0101DECA2','01DECA2','Assegurar a gestão dos recursos orçamentários sob responsabilidade do SEEx, promovendo o planejamento, a execução, o controle e o aperfeiçoamento da aplicação dos recursos, com foco na eficiência e no alinhamento às prioridades institucionais');
INSERT INTO "objetivos_dos_processos" ("codobjproc", "codprocesso", "objetivo_processo") VALUES ('0101DECA3','01DECA3','Assegurar o preparo e o emprego das OME com prontidão, eficiência e efetividade');
