INSERT INTO "objetivos_dos_processos" ("codobjproc", "codprocesso", "objetivo_processo") VALUES ('0101DECA6','01DECA6','Assegurar a condução de processos com observância da legislação aplicável e dos normativos vigentes, de forma juridicamente adequada, segura e tempestiva, resguardando a conformidade dos atos praticados e a regularidade dos procedimentos');
