INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'11I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','0101DECAEPG',10,'Desvio de Conduta - Práticas de intimidação, discriminação, favorecimento ou perseguição por interesses pessoais, comprometendo dignidade e justiça no trabalho.','Intimidação, discriminação, abuso, favorecimento ou perseguição contra subordinados por interesses pessoais ou relações inadequadas.','OEDEC 10','Ato de intimidação, discriminação, abuso, favorecimento ou perseguição contra subordinados por interesses pessoais ou relações inadequadas.','(1) Comprometimento da impessoalidade, da ética e da integridade nas relações funcionais e na gestão de pessoas.\r\n(2) Deterioração do ambiente de trabalho, com medo, desmotivação, conflitos e redução do bem-estar organizacional.\r\n(3) Prejuízo à meritocracia, à igualdade de tratamento e à confiança nas decisões da chefia.\r\n(4) Risco de denúncias, apurações internas e responsabilização administrativa dos envolvidos.\r\n(5) Queda da produtividade, do engajamento e da credibilidade institucional perante público interno e externo.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,1,1,1,1,1,1,1,1,1,NULL,1,FALSE,1,1,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'12I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','0101DECAEPG',10,'Uso indevido de autoridade - Abuso ou desvio de poder hierárquico, violando direitos e garantias legais para atender interesses indevidos, pessoais ou de terceiros.','Violação de direitos e garantias profissionais por abuso ou desvio de poder, para atender interesses indevidos ou motivações imorais.','OEDEC 10','Ato de abuso ou desvio de poder que viola direitos e garantias profissionais para atender interesses indevidos ou motivações imorais.','(1) Comprometimento da legalidade, da moralidade e da integridade na atuação administrativa.\r\n(2) Restrição indevida de direitos e garantias profissionais, com prejuízo ao ambiente institucional e à justiça organizacional.\r\n(3) Risco de nulidade de atos, contestações formais e responsabilização dos agentes envolvidos.\r\n(4) Enfraquecimento da confiança interna, da segurança institucional e da cultura de respeito às normas.\r\n(5) Danos à imagem e à credibilidade da administração perante servidores, controles e sociedade.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,2,2,2,2,2,2,2,2,2,NULL,2,FALSE,2,2,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'13I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','0101DECAEPG',10,'Uso indevido de autoridade - Coagir militar ou servidor civil a agir fora de suas atribuições ou a descumprir dever legal ou normativo.','Coação para que militar ou servidor civil atue fora de suas atribuições ou descumpra obrigações legais ou normativas.','OEDEC 10','Ato de Coação para que militar ou servidor civil atue fora de suas atribuições ou descumpra dever legal ou normativo.','(1) Comprometimento da legalidade, da integridade e da regularidade das atividades administrativas e operacionais.\r\n(2) Execução de atos irregulares, com descumprimento de normas, deveres funcionais e limites de competência.\r\n(3) Exposição do processo e da administração a nulidades, contestações e responsabilizações administrativas.\r\n(4) Geração de ambiente organizacional de medo, pressão indevida e enfraquecimento da cultura ética.\r\n(5) Prejuízos à eficiência, à confiabilidade das decisões e à credibilidade institucional perante controles e sociedade.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,3,3,3,3,3,3,3,3,3,NULL,3,FALSE,3,3,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'14I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','0101DECAEPG',10,'Nepotismo - Contratação direta sem licitação de empresa ligada a familiar de autoridade ou agente da área demandante, com favorecimento indevido.','Contratação direta sem licitação de empresa vinculada a familiar de agente ou autoridade com poder sobre a demanda ou contratação.','OEDEC 10','Ato de contratar diretamente, sem licitação, empresa vinculada a familiar de agente ou autoridade com poder sobre a demanda.','(1) Comprometimento da legalidade, da impessoalidade e da moralidade no processo de contratação.\r\n(2) Favorecimento indevido, com prejuízo à competitividade, à isonomia e à seleção da proposta mais vantajosa.\r\n(3) Risco de nulidade da contratação e de questionamentos por órgãos de controle interno e externo.\r\n(4) Instauração de apurações administrativas, com possibilidade de responsabilização dos agentes envolvidos.\r\n(5) Aplicação de sanções administrativas, inclusive rescisão contratual e impedimentos legais cabíveis.\r\n(6) Danos à imagem, à credibilidade e à confiança na integridade da administração.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,4,4,4,4,4,4,4,4,4,NULL,4,FALSE,4,4,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'15I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','0101DECAEPG',10,'Nepotismo - Uso da posição hierárquica para nomear, contratar ou favorecer parentes, cônjuge ou companheiro, em violação à impessoalidade.','Uso da posição hierárquica para nomear, contratar ou favorecer cônjuge, companheiro ou parentes, violando a impessoalidade administrativa.','OEDEC 10','Nomeação, contratação ou favorecimento de cônjuge ou parentes por autoridade hierárquica, com quebra da impessoalidade.','(1) Comprometimento da impessoalidade, da isonomia e da integridade nas contratações vinculadas à Instituição.\r\n(2) Favorecimento indevido, com distorção de critérios técnicos e administrativos na seleção de pessoal.\r\n(3) Risco de conflitos de interesse, nulidade de atos e questionamentos por órgãos de controle.\r\n(4) Instauração de apurações internas e eventual responsabilização administrativa dos envolvidos.\r\n(5) Prejuízos à credibilidade, à transparência e à confiança na atuação institucional.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,5,5,5,5,5,5,5,5,5,NULL,5,FALSE,5,5,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'16I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','0101DECAEPG',10,'Nepotismo - Contratação de familiares por empresa terceirizada ou entidade vinculada à Instituição, com favorecimento indevido.','Contratação de familiares por empresa terceirizada ou entidade vinculada à Instituição, com favorecimento indevido.','OEDEC 10','Contratação, por terceirizada ou vinculada, de familiar com favorecimento indevido, configurando nepotismo em benefício relacionado à Instituição.','(1) Comprometimento da impessoalidade e da integridade do processo de contratação ou gestão contratual.\r\n(2) Favorecimento indevido, com prejuízo à isonomia, à transparência e à legitimidade das decisões administrativas.\r\n(3) Risco de nulidade de atos administrativos e de questionamentos por órgãos de controle interno e externo.\r\n(4) Instauração de apurações, sindicâncias ou processos administrativos para responsabilização dos envolvidos.\r\n(5) Aplicação de sanções administrativas e eventual rescisão contratual, conforme a gravidade do caso.\r\n(6) Danos à imagem, à credibilidade e à confiança na Instituição perante a sociedade e partes interessadas.\r\n(7) Prejuízos à eficiência administrativa, com possibilidade de decisões inadequadas e conflitos de interesse.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,6,6,6,6,6,6,6,6,6,NULL,6,FALSE,6,6,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'21I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','01.01-DECAEPG ',10,'Inobservância de normas e regulamentos','Risco de desvios operacionais e decisões contrárias às diretrizes, decorrente de fragilidades nos fluxos de controle interno, gerando desperdício de recursos, sanções legais e severo impacto reputacional.','OEDEC 10','Desconformidade administrativa e decisória: Falhar na execução dos ritos estabelecidos para gerir atividades e recursos ou tomar decisões que violam leis e regulamentos internos da instituição.','(1) Sanções legais e multas: Penalidades aplicadas por órgãos de controle externo e fiscalização regulatória devido ao descumprimento da legislação vigente; (2) Prejuízo financeiro e desperdício: Ineficiência gerencial com perda direta ou mau uso do orçamento disponível pela falta de adesão aos fluxos corretos; e (3) Perda de credibilidade corporativa: Comprometimento da confiança pública e desgaste severo da governança institucional perante a sociedade ou investidores.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,7,7,7,7,7,7,7,7,7,NULL,7,FALSE,7,7,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'22I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','01.01-DECAEPG ',10,'Desvio de pessoal ou de recursos materiais','Risco de desvio de bens, insumos ou mão de obra para uso particular, devido a fragilidades na fiscalização e inventário, resultando em dano ao erário, ineficiência de serviços e severa responsabilização legal e institucional.','OEDEC 10','Uso indevido de patrimônio e força de trabalho: Utilização privada de veículos, máquinas, materiais, militares ou prestadores de serviços da instituição em benefício próprio ou de terceiros.','(1) Improbidade administrativa e sanções legais, com abertura de inquéritos, processos administrativos disciplinares (PAD) e ações judiciais cíveis ou criminais contra os envolvidos; (2) Prejuízo financeiro e desperdício de recursos: Desgaste prematuro do patrimônio público, consumo indevido de combustível/insumos e desperdício de horas de trabalho pagas pela instituição; (3) Interrupção e atraso de serviços oficiais: Redução da capacidade operacional da instituição devido à ausência de equipamentos ou pessoal deslocados para fins privados; e (4) Dano gravíssimo à imagem institucional: Desgaste severo da credibilidade e da confiança pública perante a sociedade e os órgãos de controle.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,8,8,8,8,8,8,8,8,8,NULL,8,FALSE,8,8,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'02I0101DECA2','01DECA2','Gestão de Recursos Orçamentários sob responsabilidade do SEEx',NULL,10,'Possibilidade de contingenciamento, bloqueio ou corte do limite de movimentação de créditos orçamentários destinados ao SEEx','Possibilidade de contingenciamento, bloqueio ou corte de créditos orçamentários do SEEx, por frustração de receita ou restrições fiscais federais, comprometendo despesas planejadas, ações institucionais e metas do exercício.','OEDEC 10','Contingenciamento, bloqueio ou corte de limite de movimentação de créditos do SEEx.','Atraso ou inviabilização parcial da execução orçamentária, com impactos sobre contratos, projetos, custeio e metas institucionais.','DEC; EME','Risco Inerente',NULL,9,9,9,9,9,9,9,9,9,NULL,9,FALSE,9,9,'Estratégicos',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'01I0102DECA4','02DECA4','Gestão da Folha de Pagamento do Pessoal Contratado por Tempo Determinado no SEEx',NULL,10,'Risco de processamento intempestivo ou irregular da folha do PCTD no SEEx','Risco de processamento intempestivo ou irregular da folha do PCTD no SEEx, podendo gerar falhas na remuneração, descumprimento legal e comprometimento da conformidade administrativa e orçamentária.','OEDEC 10','Falha ou atraso no processamento da folha do PCTD no SEEx.','(1) Atraso ou erro no pagamento dos contratados temporários, com prejuízo à regularidade da folha e à segurança administrativa do processo; (2) Descumprimento de obrigações legais, administrativas e orçamentárias, com necessidade de retrabalho, correções e fragilização dos controles internos; e (3) Comprometimento da continuidade da força de trabalho temporária, inclusive com eventual desligamento de PCTD por falta de recursos para pagamento.','DEC, Diretorias, Gpt E e OME','Risco Inerente',NULL,10,10,10,10,10,10,10,10,10,NULL,10,FALSE,10,10,'Estratégicos',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('02','09I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','0101DECAEPG',10,'Desvio de Conduta - Falta de profissionalismo, honestidade, lealdade, idoneidade ntegridade, imparcialidade, responsabilidade, seriedade, eficiência, qualidade e/ou urbanidade.','Deixar de exercer as atribuições com ética, integridade, imparcialidade, responsabilidade, eficiência, qualidade e urbanidade.','OEDEC 10','Ato de omitir ou exercer atribuições sem ética, integridade, imparcialidade, responsabilidade, eficiência, qualidade e urbanidade.','(1) Comprometimento da qualidade, da regularidade e da confiabilidade dos atos e processos administrativos.\r\n(2) Prejuízo à ética, à imparcialidade e à integridade na prestação do serviço público.\r\n(3) Redução da eficiência, com falhas, omissões, retrabalho e baixa qualidade nas entregas.\r\n(4) Enfraquecimento da confiança interna e externa na atuação dos agentes e da administração.\r\n(5) Risco de apurações, responsabilização funcional e danos à imagem institucional.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,11,11,11,11,11,11,11,11,11,NULL,11,FALSE,11,11,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('01','01I0101DOM04','01DOM04','Gestão de Obras Militares com indício de paralisação','0101DOM04',7,'Paralização de Obra Militar.','Em virtude de indícios de rescisão contratual, podem ocorrer impugnações administrativas e judiciais, bem como paralisação ou embargo da obra, gerando perda de RPNP e impactando a gestão dos contratos de obras militares.','OEDEC 10','Indício de paralização de Obra Militar.','(1) Comprometimento da legalidade e da ética administrativa; (2) Responsabilização disciplinar, civil ou penal do agente; (3) Anulação de atos administrativos praticados; (4) Danos à imagem e à credibilidade institucional; e (5) Riscos jurídicos e administrativos para a organização.','Gab Cmt Ex; EME; DGP; DEC; e DOM.','Risco Inerente',NULL,12,12,12,12,12,12,12,12,12,NULL,12,FALSE,12,12,'Estratégicos',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('24','04I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','0101DECAEPG',10,'Risco de Integridade - Assédio Moral e Sexual','Relações assimétricas e falhas preventivas podem levar a assédio moral e sexual, gerando danos à vítima, sanções, perda de confiança e produtividade.','OEDEC 10','Ocorrência de condutas caracterizadas como assédio moral e assédio sexual no ambiente organizacional.','Dano moral e psicológico à vítima, responsabilização legal da organização, perda de confiança, queda de produtividade, aumento do turnover, sanções administrativas.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,13,13,13,13,13,13,13,13,13,NULL,13,FALSE,13,13,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'02I0101DOMSG1','01DOMSG1','Autorização de abertura de edital PCTD no Sistema de Obras Militares','0101DOMSG1',7,' Atraso ou falha na confeção de nota parra Adt BARADT BAR','Risco de atraso ou falha na emissão da nota da ADT BAR pode impactar o planejamento orçamentário e logístico da movimentação militar, comprometendo o pagamento tempestivo de ajuda de custo, transporte de bagagem e despesas correlatas.','OEE04','Atraso ou falha na confecção da nota para publicação em Aditamento BAR após\r\nrecebimento do DIEx.','- Atraso, prejuízo ao planejamento e descumprimento de prazos.\r\n- Prejuízo ao planejamento orçamentário e logístico da movimentação do militar.','Gab Cmt Ex; EME; DGP; DEC; e DOM.','Risco Inerente',NULL,14,14,14,14,14,14,14,14,14,NULL,14,FALSE,14,14,'Aceitáveis',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('29','08I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','0101DECAEPG',10,'Conflito de Interesse - Exercício, direto ou indireto, de atividade incompatível com as atribuições do cargo público.','Possibilidade de o agente público exercer atividade incompatível com o cargo, gerando conflito de interesses, responsabilização legal, invalidação de atos e danos à imagem e à legalidade institucional.','OEDEC 10','Exercício de atividade incompatível com o cargo público, direta ou indiretamente, gerando conflito de interesses, responsabilização do agente e danos à legalidade e à imagem institucional.','(1) Quebra de imparcialidade e confiança institucional; \t(2) Conflito de interesses; (3) Responsabilização administrativa, civil ou penal do agente; (4) Anulação de atos administrativos; e (5) Dano à imagem institucional.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,15,15,15,15,15,15,15,15,15,NULL,15,FALSE,15,15,'De Integridade','01DECA1');
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'03I0101DOM01','01DOM01','Conclusão e Entrega de Obras Militares no SEEx','0101DOM01',7,'Obras Militares, sob a gestão da DOM, paralisadas ou com velocidade zero.','Em virtude de falhas nos estudos preliminares de projetos, com emissão de pareceres incompletos ou imprecisos, podem ocorrer atrasos no início da obra e retrabalho nos serviços preliminares contratados, impactando a gestão de obras militares.','OEDEC 10','Emissão de parecer incompleto/impreciso sob a ótica de Obras Militares.','Atraso no início da obra e retrabalho.','Gab Cmt Ex; EME; DGP; DEC; e DOM.','Risco Inerente',NULL,16,16,16,16,16,16,16,16,16,NULL,16,FALSE,16,16,'Estratégicos',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'10I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','0101DECAEPG',10,'Risco de Integridade - Quebra das propriedades de proteção das informações','Possibilidade de comprometimento da confidencialidade, integridade ou disponibilidade das informações do DEC, por falhas de controle ou vulnerabilidades, com impactos operacionais, legais, reputacionais e institucionais.','OEDEC 10','Quebra das propriedades de proteção das informações','(1) Comprometimento da continuidade dos processos e da tomada de decisão administrativa.\r\n(2) Vazamento, alteração, perda ou indisponibilidade de informações e documentos.\r\n(3) Prejuízos operacionais, com atrasos, retrabalho e interrupção de atividades.\r\n(4) Responsabilização administrativa e legal por falhas de controle ou vulnerabilidades.\r\n(5) Danos reputacionais e perda de credibilidade institucional.\r\n(6) Impactos à segurança institucional e ao cumprimento da missão do DEC.','DEC, Diretorias, Gpt E','Risco Inerente',NULL,17,17,17,17,17,17,17,17,17,NULL,17,FALSE,17,17,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'01I0101DOM03','01DOM01','Conclusão e Entrega de Obras Militares no SEEx','0101DOM04',7,'Falta de elaboração do TEREO, das onbras militares sob a gestão da DOM.','Risco de ausência de TEREO pode gerar saldos alongados na conta contábil de obras em andamento, produzindo inconformidades em auditorias dos órgãos de controle e comprometendo a gestão eficiente dos contratos de obras militares em execução.','OEDEC 10','Existência de saldo alongado na conta contábil obras em andamento.','Inconformidades nas auditorias dos orgãos de controle.','Gab Cmt Ex; EME; DGP; DEC; e DOM.','Risco Inerente',NULL,18,18,18,18,18,18,18,18,18,NULL,18,FALSE,18,18,'Estratégicos',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('28','06I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','0101DECAEPG',10,'Ameaças à imparcialidade e à autonomia técnica - Atuar com parcialidade por pressão indevida, abuso de poder ou tráfico de influência.','Possibilidade de o agente público adotar conduta inadequada na mediação de conflitos, gerando favorecimentos ou decisões parciais, com prejuízo à imparcialidade, efetividade dos processos e ao clima organizacional.','OEDEC 10','Condução inadequada na resolução de conflitos internos,  gerando favorecimentos ou decisões parciais, com prejuízo à imparcialidade, efetividade dos processos e ao clima organizacional.','(1) Quebra de imparcialidade e confiança institucional; (2)  Desmotivação e insegurança dos servidores; (3) Ambiente de trabalho hostil e improdutivo; (4)  Judicialização de conflitos e aumento de passivos trabalhistas; (5) Danos à imagem institucional e perda de credibilidade da liderança.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,19,19,19,19,19,19,19,19,19,NULL,19,FALSE,19,19,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('30','07I0101DECAEPG','01DECAEPG',NULL,'0101DECAEPG',10,'Conflito de Interesse -  Favorecimento indevido a Pessoa Jurídica vinculada a parente em até 3º Grau','Possibilidade de agente público conceder favorecimento indevido a pessoa jurídica vinculada a cônjuge ou parente até 3º grau, influenciando decisões para obter benefício privado ou causar prejuízo ao erário.','OEDEC 10','Concessão, por agente público, de tratamento privilegiado a pessoa jurídica vinculada a parente até 3º grau, gerando conflito de interesses, possível desvio de finalidade e afronta aos princípios da legalidade, impessoalidade e moralidade.','(1) Enriquecimento ilícito ou desvio de recursos públicos; (2) Perda de legitimidade e confiança institucional; (3) Configuração de ato de improbidade administrativa; (4) Sanções legais e administrativas ao agente público; (5) Danos à imagem da instituição e responsabilização por órgãos de controle.','DEC, Diretorias,. Assessorias, Gabinete, PENSE, GptE e OME','Risco Inerente',NULL,20,20,20,20,20,20,20,20,20,NULL,20,FALSE,20,20,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'17I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','01.01-DECAEPG ',10,'Risco de Fraude','Risco de fraude por indução ao erro mediante artifício, causado por vulnerabilidades em controles operacionais, resultando na obtenção de vantagens ilícitas com prejuízos financeiros à instituição.','OEDEC 10','Ocorrência de conluio entre agentes internos ou externos para fraudar, desviar ou manipular recursos orçamentários em processos administrativos.','(1) Prejuízo financeiro imediato; (2) Custos de remediação, com gastos extras com auditorias investigativas, perícias técnicas e processos de recuperação de ativos; (3) Retrabalho operacional; (4) Desgaste reputacional e perda de credibilidade perante parceiros, fornecedores, órgãos de controle e a sociedade; (5) Responsabilização jurídica e passivos legais, multas regulatórias ou processos judiciais por falhas na guarda e gestão de recursos; e (6) Perda de eficiência.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,21,21,21,21,21,21,21,21,21,NULL,21,FALSE,21,21,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'18I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','01.01-DECAEPG ',10,'Risco de Colusão','Risco de fraude orçamentária via conluio entre agentes em licitações, causado por fragilidades na governança de contratos, resultando em desvio de recursos públicos, perda de eficiência e severo impacto à imagem institucional.','OEDEC 10','Fraude ou desvio de recursos orçamentários por meio de conluio (colusão) entre agentes internos e externos em processos administrativos e licitatórios.','(1) Prejuízo financeiro direto (dano ao erário);\r\n(2) Perda da eficiência operacional; e\r\n(3)  Severo dano à imagem e credibilidade da instituição.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,22,22,22,22,22,22,22,22,22,NULL,22,FALSE,22,22,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('32','05I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','0101DECAEPG',10,'Conflito de Interesse - Recebimento Indevido de presentes ou vantagens por agente público, de parte interessada em decisão sob sua influência.','Possibilidade de agente público receber vantagem, presente ou hospitalidade de parte interessada em decisão sob sua influência, fora dos limites legais e normativos estabelecidos, comprometendo a imparcialidade e a integridade da atuação pública.','OEDEC 10','Recebimento indevido de vantagem, presente ou hospitalidade por agente público, de parte interessada em decisão sob sua influência, em desconformidade com normas legais, comprometendo a imparcialidade e a integridade da função pública.','(1) Configuração de conflito de interesses; (2) Comprometimento da imparcialidade nas decisões; (3) Sanções disciplinares, administrativas e penais ao agente; (4) Danos à imagem institucional e à confiança pública; (5) Anulação de atos administrativos contaminados por vício de vontade.','DEC, Diretorias,. Assessorias, Gabinete, PENSE, GptE e OME','Risco Inerente',NULL,23,23,23,23,23,23,23,23,23,NULL,23,FALSE,23,23,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'19I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','01.01-DECAEPG ',10,'Risco de Corrupção','Risco de aceitação de vantagem indevida por agente público, devido a falhas na supervisão e controle do cargo, gerando perda da lisura nos serviços públicos e severo impacto reputacional à instituição.','OEDEC 10','Aceitação ou solicitação de vantagem indevida por um agente público, utilizando-se do poder ou da posição dominante de seu cargo para favorecer interesses privados em troca de uma prestação de serviço.','Quebra da impessoalidade e da lisura nos serviços prestados.Severo impacto reputacional com perda da confiança pública na instituição.Responsabilização legal dos envolvidos administrativamente e criminalmente.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,24,24,24,24,24,24,24,24,24,NULL,24,FALSE,24,24,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES (NULL,'20I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','01.01-DECAEPG ',10,'Risco de injustiça','Risco de erro em processos de responsabilização decorrente de falhas em apurações e julgamentos, resultando em injustiças individuais, prejuízos financeiros com indenizações e sérios danos à imagem e governança da instituição.','OEDEC 10','Culpar um agente inocente (erro por ação) ou deixar de punir o verdadeiro responsável por uma irregularidade (erro por omissão).','(1) Indenizações e custos legais, com gastos com ações judiciais para reparação de danos morais e materiais às pessoas afetadas injustamente; (2) Desgaste reputacional severo e perda de credibilidade pública e institucional pela percepção de injustiça ou impunidade; e (3) Prejuízo ao clima organizacional com perda de confiança das equipes nos processos internos de governança e corregedoria.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,25,25,25,25,25,25,25,25,25,NULL,25,FALSE,25,25,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('27','02I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','0101DECAEPG',10,'Desvio de conduta - Condutas pessoais ofensivas, humilhantes ou abusivas que atinjam a dignidade e a integridade física ou psíquica e prejudiquem o trabalho.','Desvios de conduta podem resultar em práticas abusivas e reiteradas no ambiente de trabalho, visando humilhar, desqualificar, ofender ou constranger um indivíduo, desestabilizando-o emocionalmente, comprometendo sua atuação e impactando a imagem do SEEx.','OEDEC 10','Conduta abusiva, intencional e reiterada de agente público, no ambiente de trabalho, entre pares ou superiores e subordinados, buscando humilhar, desqualificar, ofender ou constranger um indivíduo, desestabilizando-o emocionalmente e profissionalmente.','Perda de confiança na instituição, além de possíveis prejuízos financeiros e reputacionais para a administração pública.','DEC, Diretorias, OM Eng, Gpt E','Risco Inerente',NULL,26,26,26,26,26,26,26,26,26,NULL,26,FALSE,26,26,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('13','03I0101DECAEPG','01DECAEPG','Gerenciamento de Riscos de Integridade no SEEx','0101DECAEPG',10,'Conflito de Interesse - Atuação Indevida em Favor de Interesses Privados','Possibilidade de agente público intermediar interesses privados, ainda que informalmente, junto à administração, atuando como procurador, consultor ou assessor, em desacordo com os princípios da legalidade, impessoalidade e moralidade.','OEDEC 10','Atuação indevida em favor de interesses privados ainda que informalmente, junto à administração, atuando como procurador, consultor ou assessor, em desacordo com os princípios da legalidade, impessoalidade e moralidade.','(1) Comprometimento da legalidade e da ética administrativa; (2) Comprometimento da isenção decisória; (3) Responsabilização disciplinar, civil ou penal do agente; (4) Anulação de atos administrativos praticados; (5) Danos à imagem e à credibilidade institucional; e (6) Riscos jurídicos e administrativos para a Organização.','DEC, Diretorias, Gpt E e OME','Risco Inerente',NULL,27,27,27,27,27,27,27,27,27,NULL,27,FALSE,27,27,'De Integridade',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('12','01I0201DOC02','01DOC02','Prestação de Contas (Final ou Parcial) de Instrumentos de Parceira de Obras de Cooperação','0201DOC2',2,'Inexecução parcial ou total do objeto pactuado em Instrumento de parceria, sob a gestão da DOC.','Por problemas técnicos e administrativos, o DEC pode não concluir o objeto do instrumento de parceria no prazo-limite, resultando em danos à imagem da Força, entraves administrativos e possíveis sanções legais e administrativas pelos órgãos de controle.','OEDEC 10','Inexecução parcial ou total do objeto pactuado (P Trab) no Instrumento de Parceria.','Inexecução parcial ou total do respectivo P Trab, com potencial comprometimento dos resultados pactuados, risco à observância dos princípios da legalidade e da eficiência administrativa, prejuízo ao erário e eventual responsabilização dos agentes públicos e demais envolvidos, nos termos da legislação vigente. Prejuízos à imagem da Força.','DEC; EME; DOC; DNIT','Risco Inerente',NULL,28,28,28,28,28,28,28,28,28,NULL,28,FALSE,28,28,'Estratégicos',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('14','02I0101DECA4','01DECA4','Gestão dos PDR, Instrumentos de Parceria e Emendas Parlamentares','0101DECA4',10,'Inexecução total ou parcial de atividade patrocinada por Emenda Parlamentar, sob a gestão do DEC.','Em virtude de fatores de risco variados, pode ocorrer inexecução total ou parcial da atividade custeada por emenda parlamentar, exigindo devolução de crédito ou cancelamento de empenho em restos a pagar e impactando a imagem institucional da Força.','OEDEC 10','Inexecução total ou parcial de atividade patrocinada por Emenda Parlamentar','Comprometimento da imagem institucional do Exército e responsabilização administrativa dos agentes públicos envolvidos.','DEC, Diretorias, Gab Cmt Ex, EME, Gpt E','Risco Inerente',NULL,29,29,29,29,29,29,29,29,29,NULL,29,FALSE,29,29,'Estratégicos',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('26','01I0301DOC01','01DOC01','Celebração e Gestão dos Instrumentos de Parceria de Obras de Cooperação','0301DOC1',2,'Inconsistências, omissões, inadequações formais ou materiais na minuta do Instrumento de Parceria','Risco de inconsistências na minuta do Instrumento de Parceria que possam comprometer a execução parcial ou total do P Trab, afetando os resultados pactuados, a legalidade dos atos administrativos e a responsabilização dos agentes envolvidos.','OEDEC 10','Ocorrência de inconsistências, omissões, inadequações formais ou materiais no Instrumento de Parceria a ser celebrado',' Não aceitação do Instrumento de Parceria. Na hipótese de sua assinatura, poderá ocorrer a inexecução parcial ou total do respectivo P Trab, com potencial comprometimento dos resultados pactuados, risco à observância dos princípios da legalidade e da eficiência administrativa, prejuízo ao erário e eventual responsabilização dos agentes públicos e demais envolvidos, nos termos da legislação vigente.','DEC, Diretorias, EME, Gpt E','Risco Inerente',NULL,30,30,30,30,30,30,30,30,30,NULL,30,FALSE,30,30,'Estratégicos',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('15','01I0101DECA6','01DECA6','Gestão e Assessoramento de Processos Jurídicos no DEC','2701DECA6',15,'Identificação de erros na documentação e na tramitação de processos, sob a gestão da A/5 DEC..','Em virtude de falhas na documentação e na instrução de processos jurídicos, pode ocorrer análise inadequada ou malsucedida, resultando em posicionamento jurídico equivocado e impactando a tomada de decisão do DEC ou o direito solicitado.','OEDEC 10','Identificação de fatores externos em desconformidade (erros na documentação e na tramitação do processo).','Inadimplemento da análise jurídica referente à pretensão do autor, bem como a existência de posicionamentos jurídicos imprecisos.','DEC; Diretorias; e Outros','Risco Inerente',NULL,31,31,31,31,31,31,31,31,31,NULL,31,FALSE,31,31,'Estratégicos',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('33','01I0101DECA1','01DECA1','Gestão de Recursos Humanos e Talentos','0101DECA1',12,'Não ocorrência da movimentação do militar especializado.','Risco decorrente da ausência de movimentação solicitada pode impedir o recebimento de militar especializado em função ou cargo crítico pelo DEC, Diretorias, Gpt E ou OME, comprometendo a capacidade operativa da OM e os objetivos setoriais do SEEx.','OEDEC1',NULL,'O não preenchimento do claro existente com o militar especializado para determinada função ou cargo crítico nas OM do SEEx.','DEC, Diretorias subordinadas, Gpt E e OM do SEEx.','Risco Inerente',NULL,32,32,32,32,32,32,32,32,32,NULL,32,FALSE,32,32,'Estratégicos','01DECA3');
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('34','01I0101DECA2','01DECA2','Gestão de Recursos Orçamentários sob responsabilidade do SEEx','0123DECA2',13,'Instabilidade do Painel BI por falha de TI','Em virtude de falhas de TI, pode ocorrer pane na plataforma do Painel BI, impedindo o desenvolvimento da capacidade planejada e impactando o estado final desejado pela Assessoria 2 do DEC.','OEDEC 10','Manter o PAINEL BI funcionando.','Mitigar para que o PAINEL BI esteja estável.','MD; DEC; OMDV; Gpt E; CRO e o Btl Const.','Risco Inerente',NULL,33,33,33,33,33,33,33,33,33,NULL,33,FALSE,33,33,'Estratégicos',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('35','01I0101DECA3','01DECA3','Preparo e emprego das OM de Engenharia','0101DECA3',9,'Consciência Situacional sobre Operações de Engenharia em curso desatualizada ou inverídica.','Em virtude de falhas no recebimento de informações, o DEC pode não dispor de visão precisa do andamento das operações de engenharia em curso, impactando a consciência situacional do SEEx.','OEDEC 10','Informações equivocadas prestadas atinentes às Operações','O DEC não terá uma real situação do andamento das Operações','DEC, Gpt E, CMilA e OME','Risco Inerente',NULL,34,34,34,34,34,34,34,34,34,NULL,34,FALSE,34,34,'Estratégicos',NULL);
