INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('05','01I0101DECA5','01DECA5','Gestão da Comunicação Estratégica do SEEx','2601DECA5',14,'Eventos mal-sucedidos de comunicação estratégica','Em virtude de falhas no gerenciamento de evento sob coordenação do SEEx, podem ocorrer repercussões negativas na imagem da Engenharia e do Exército, impactando o OES do SEEx.','OEE10','Atividades malsucedidas com o público interno','Criar uma crise de imagem com o público interno','DEC; SEEx; CMilA; CCOMSEX; RM.','Risco Inerente',NULL,36,36,36,36,36,36,36,36,36,NULL,36,FALSE,36,36,'Estratégicos',NULL);
