INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('03','02I0201DOC02','01DOC02','Prestação de Contas (Final ou Parcial) de Instrumentos de Parceira de Obras de Cooperação','0201DOC02',2,'Não entrega da Prestação de Contas Final (PCF) no prazo, das obras de cooperação sob a gestão da DOC.','Em virtude de eventual atraso injustificado na entrega da PCF pela OM do SOC, pode ocorrer impossibilidade de análise pelo concedente, com potencial instauração de TCE e impacto na credibilidade do EB junto à instituição parceira.','OEDEC 10','Não cumprimento dos prazos superiores a 120 dias para o envio da PCF do TED e 60 dias para o TCR','A DOC/DEC não terá a real situação técnica e financeira do encerramento do Instrumento de Parceria','DEC; DOC; Cmdo Mil A; Gpt E, OME','Risco Inerente',NULL,51,51,51,51,51,51,51,51,51,NULL,51,FALSE,51,51,'Estratégicos',NULL);
INSERT INTO "riscos" ("nr_risco", "codrisco", "codprocesso", "processo", "codobjproc", "macroprocesso", "risco", "descricao_risco", "oee_oes", "eventos", "consequencias", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "gatilhos", "marcado", "controle_de_deteccao", "controle_preventivo", "categoria", "posto_grad_nome_prisc") VALUES ('25','01I0101DOMSG1','01DOMSG1','Autorização de abertura de edital PCTD no Sistema de Obras Militares','0101DOMSG1',7,' Atraso ou falha na confeção de nota parra Adt BARADT BAR','Em virtude de atraso ou falha na confecção da nota para ADT BAR, podem ocorrer prejuízos ao planejamento orçamentário e logístico da movimentação militar, afetando o pagamento de ajuda de custo e o transporte de bagagem e pessoal.','OEE04','Atraso ou falha na confecção da nota para publicação em Aditamento BAR após\r\nrecebimento do DIEx.','- Atraso, prejuízo ao planejamento e descumprimento de prazos.\r\n- Prejuízo ao planejamento orçamentário e logístico da movimentação do militar.','Gab Cmt Ex; EME; DGP; DEC; e DOM.','Risco Inerente',NULL,52,52,52,52,52,52,52,52,52,NULL,52,FALSE,52,52,'Aceitáveis',NULL);
