INSERT INTO "riscos_residuais" ("codriscores", "codprocesso", "codrisco", "risco_residual", "descricao_risco", "consequencias", "eventos", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "fator_de_risco_social1", "fator_de_risco_tecnologico1", "imagem1", "gatilhos", "posto_grad_nome_prisc") VALUES ('03.R.01.01-DECAEPG','01DECAEPG','03I0101DECAEPG','Conflito de Interesse - Incompatibilidade de Atividades com as Atribuições do Cargo','Possibilidade de agente público intermediar interesses privados, ainda que informalmente, junto à administração, atuando como procurador, consultor ou assessor, em desacordo com os princípios da legalidade, impessoalidade e moralidade.','(1) Comprometimento da legalidade e da ética administrativa; (2) Responsabilização disciplinar, civil ou penal do agente; (3) Anulação de atos administrativos praticados; (4) Danos à imagem e à credibilidade institucional; e (5) Riscos jurídicos e administrativos para a Organização.','Atuação indevida em favor de interesses privados.','DEC, Diretorias, Assessorias, PENSE, GptE e OME','Risco Residual',NULL,3,3,3,3,3,3,3,3,3,NULL,3,3,NULL,3,NULL);
INSERT INTO "riscos_residuais" ("codriscores", "codprocesso", "codrisco", "risco_residual", "descricao_risco", "consequencias", "eventos", "orgaos_envolvidos", "classificacao_do_risco", "data", "fator_de_risco_administrativo", "fator_de_risco_economico", "fator_de_risco_material", "fator_de_risco_meio_ambiente", "fator_de_risco_operacional", "fator_de_risco_pessoal", "fator_de_risco_politico", "fator_de_risco_social", "fator_de_risco_tecnologico", "imagem", "fator_de_risco_social1", "fator_de_risco_tecnologico1", "imagem1", "gatilhos", "posto_grad_nome_prisc") VALUES ('05.R.01.01-DECAEPG','01DECAEPG','05I0101DECAEPG','Risco de Conflito de Intersse - Recebimento Indevido de Presentes ou Vantagens','Possibilidade de agente público receber vantagem, presente ou hospitalidade de parte interessada em decisão sob sua influência, fora dos limites legais e normativos estabelecidos, comprometendo a imparcialidade e a integridade da atuação pública.','(1) Configuração de conflito de interesses; (2) Comprometimento da imparcialidade nas decisões; (3) Sanções disciplinares, administrativas e penais ao agente; (4) Danos à imagem institucional e à confiança pública; (5) Anulação de atos administrativos contaminados por vício de vontade.','Recebimento indevido de vantagem por parte de agente público','DEC, Diretorias,. Assessorias, Gabinete, PENSE, GptE e OME','Risco Residual',NULL,4,4,4,4,4,4,4,4,4,NULL,4,4,NULL,4,NULL);
