INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0101I0201DECAEPG','01AEPG','01DECAEPG','0101I02DECAEPG','Prevenção de conduta atentatória à integridade - Assédio Moral por meio do monitoramento do ambiente','Controle Preventivo','Mitigação da probabilidade de ocorrência de conduta atentatória à integridade - Assédio Moral','Mitigar','Realizar o monitoramento contínuo do ambiente de trabalho, por meio da avaliação do clima organizacional, promoção de atividades de conscientização e respeito e da cpacitação das lideranças',19);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0101I0202DECAEPG','01AEPG','01DECAEPG','0101I02DECAEPG','Monitoramento dos gatilhos relacionados ao assédio moral, com a finalidade de identificar possíveis desvios de conduta, registrando as evidências correspondentes conforme estabelecido no Plano de Integridade do DEC.','Controle de Detecção','Mitigação da probabilidade de ocorrência de conduta atentatória à integridade - Assédio Moral','Mitigar','Priorizar a implementação do Plano de Contingência, notificando a Alta Administração sobre o DEC. O tratamento do tema deve observar o respeito e a devida consideração às vítimas envolvidas. Deve-se assegurar a observância dos princípios estabelecidos pela Lei nº 9.784/1999 (Processo Administrativo), incluindo a legalidade, impessoalidade, moralidade, publicidade, eficiência, segurança jurídica e razoabilidade.',20);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0101I0301DECA4','02DECA4','01DECA4','0101I03DECA4','Acompanhamento quinzenal da contratação das Atividades custeadas por Emendas Parlamentares','Controle Preventivo','Mitigação da probabilidade de riscos da Inexecução de atividades custeadas por Emendas Parlamentares','Mitigar','Coordenação DEC/Gab Cmt Ex, em A-1 das atividaes que serão propostas a serem custeadas por Emenda Parlamentar. Acompanhamento quinzenal do processo de contratação das atividades custeadas por Emendas Prlamentares.',21);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0101I0301DOC','01DOC02','01DOC01','0101I03DOC','Acompanhamento dos indicadores de produtividade, prazo e custo do Plano de Trabalho do Instrumento de Parceria','Controle Preventivo','Mitigação dos riscos de Inexecução total ou parcial do Ptrab','Mitigar','A Organização Militar (OM) executante deverá emitir boletins de acompanhamento do Ptrab mensalmente, bem como no início e ao término de cada etapa, registrando essas informações no Business Intelligence (BI) da A/4 do DEC.',22);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0101I0302DOC','01DOC02','01DOC01','0101I03DOC','- Mitigação dos impactos de uma provável inexecução de atividade custeada por Emenda Parlamentar.','Controle de Detecção','Mitigação dos impactos decorrentes de inexecução total ou parcial de atividades custeadas por Emendas Parlamentares','Mitigar','- Buscar alterar o objeto custeado por Emenda Parlamentar a fim de evitar a perda de recurso',23);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0102I01012DPIMA','02DPIMA','02DPIMA','0102I01DPIMA','Relatórios mensais de acompanhamento do projeto. Graficos dos valores empenhados que são solução de problemas do diagnostico e graficos do avanço das OM pelo processos de certificação.','Controle Preventivo','Acompanhamento do preenchimento e dos indices de conformidade ambiental','Mitigar','Cobrar pela alta direção a entrega do diagostico e instruir as Om de como solucionar seus desvios e as RM em como apoiar as OM nessa solução.',24);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0102I0101DECA2','01DECA2','01DECA2','0101I01DECA2','Carga do diaria do POWER BI e, também, conferência entre o Tesouro Nacional X POWER BI. Power BI dos valores empenhados, liquidados e Restos a pagar liquidados, não liquidados e não processados. Recolher Saldos não liquidados. Para evitar RP não liquidados.','Controle Preventivo','Disponibilização de um profissional de sobreaviso na DOM para sanar panes de TI no Power BI','Mitigar','Realizar aditoria diaria no PAINEL BI e, também, verificar junto a SG3 a importância de manter um militar dedicado ao PAINEL BI.',25);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0102I0101DECA3','01DECA3','01DECA3','0101I01DECA3','Relatórios diários de acompanhamento das informações dos Gpt E e OME.','Controle Preventivo','Acompanhamento das informações sobre as Op Engenharia','Mitigar','Buscar reduzir as falhas nas informações e corrigir antecipadamente.',26);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0102I0101DECA4','01DECA4','01DECA4','0101I01DECA4','Relatórios mensais de acompanhamento do projeto. Power BI dos valores empenhados e liquidados. Power BI das entregas.','Controle Preventivo','Elaborar os PDRAEng','Mitigar','Buscar reduzir o tempo de acesso a previsibilidade de cortes na LOA.',27);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0102I0101DECA6','01DECA6','01DECA6','0102I01DECA6','Verificação atenta da documentação apresentada pelo Demandante, identificar os erros na documentação; Verificação atenta da legislação em vigor, agir sempre com imparcialidade e correção; e Processos digitais.','Controle Preventivo','Conferência dos fatores externos em desconformidade ao processo','Mitigar','Buscar reduzir as falhas na tramitação dos processos e documentos.',28);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0102I0101DECGAB','01DECGAB','01DECGAB','0102I01DECGAB','Relatórios semanais, através de planilha do excel, disponibilizada na intranet do Departamento para acompanhamento constante de todos os interessados, com contato dos fornecedores e, também, contagem de prazo da entrega dos materiais.','Controle Preventivo','0102I010101DECGAB','Mitigar','Buscar anular a possibilidade de atraso/não entrega dos materiais.',29);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0102I0101DECPENSE','01DECPENSE','01DECPENSE','0102I01DECPENSE','Relatórios mensais de acompanhamento do projeto. Power BI dos valores empenhados e liquidados. Power BI das entregas.','Controle Preventivo','Acompanhar junto ao DEC o planejamento de descentralização de créditos do Programa','Mitigar','Agir junto ao EME e A/2 do DEC sobre a necessidade de manutenção dos créditos e monitorar a descentralização.',30);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0102I0101DPE','02DPE','01DPE01','0102I01DPE','Relatórios mensais de acompanhamento do projeto.','Controle Preventivo','Acompanhamento da execucução do projeto básico dos empreendimentos','Mitigar','Buscar reduzir as falhas na documentação do projeto e corrigir antecipadamente os problemas.',31);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0102I0102DECA2','01DECA2','01DECA2','0101I01DECA2','Auditorias diárias para detectar as possíveis anomalias do sistema orçamentário do DEC.','Controle de Detecção','Reiniciar o Power BI','Evitar','Realizar runiões com o Vice-chefe do DEC e suas OMDV(s). Emitir DIEx para os Cmdo Militar de àrea e, também, Gpt E e Btl de Const.',32);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0102I0102DECA3','01DECA3','01DECA3','0101I01DECA3','Relatórios diários com as informações sobre as Op de Engenharia.','Controle de Detecção','Corrigir as informações sobre as Op Engenharia','Mitigar','Buscar se antecipar com as informações e verificar a correção das mesmas antes de apresentar a consciência situacional ao DEC.',33);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0102I0102DECA6','01DECA6','01DECA6','0102I01DECA6','Corrigir a documentação apresentada pelo Demandante; e\r\nProcessos digitais.','Controle de Detecção','Conferência dos fatores externos em desconformidade ao processo','Mitigar','Buscar reduzir as falhas na tramitação dos processos e documentos.',34);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0102I0102DECPENSE','01DECPENSE','01DECPENSE','0102I01DECPENSE','Relatórios mensais de acompanhamento do projeto. Power BI dos valores empenhados e liquidados. Power BI das entregas.','Controle de Detecção','Rebalancear o planejamento dos projetos do PENSE e as suas execuções.','Aceitar','Buscar outras fontes de financiamento. Recolher créditos antes de inscrever em RP. Rebalancear o Programa e propor novo cronograma de desembolso que permita acomodar o orçamento reduzido.',35);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0102I0201DECPENSE','04DECPENSE','01DECPENSE','0102I02DECPENSE','Monitorar novas demandas de projetos no SEEx que possam ser propostas ao PENSE','Controle Preventivo','Divulgação dos projetos em curso e conscientização de suas importâncias','Compartilhar','Acompanhar, em todas as reuniões situacionais e reuniões de coordenção DEC/Dir/Gpt E, as principais demandas apresentadas pelas Diretorias e Gpt E, de modo a monitorar o cenário e se preparar para as mudanças eventualmente propostas.',36);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0102I0202DECPENSE','04DECPENSE','01DECPENSE','0102I02DECPENSE','Monitorar novas demandas de projetos no SEEx que possam ser propostas ao PENSE','Controle de Detecção','Proposição de aumento do orçamento do PENSE para acomodar novos projetos propostos','Compartilhar','Propor, junto ao demandante de novo projeto, que apresente a fonte de recurso orçamentário e o devido aporte de recursos, compatível com a estimativa dos custos do projeto proposto.',37);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0102I0301DECPENSE','05DECPENSE','01DECPENSE','0102I03DECPENSE','Monitorar possíveis desligamentos de pessoal no PENSE','Controle Preventivo','Desenvolver um plano de recompletamento de pessoal especializado em G Pgm','Mitigar','Monitorar possíveis causas de desligamento de pessoal no PENSE, tais como: fechamento do tempo limite de convocação como PTTC, insatisfação no exercício da função, propostas de outros setores ou órgãos e motivações pessoais.',38);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0102I0302DECPENSE','05DECPENSE','01DECPENSE','0102I03DECPENSE','Verificar possíveis desligamentos de pessoal no PENSE','Controle de Detecção','Executar o plano de recompletamento de pessoal especializado em G Pgm','Mitigar','Substituir, tão logo quanto possível, o profissional desligado, proporcionando um treinamento adequado ao substituto, de forma a reduzir a solução de continuidade.',39);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0201I0101DMESSAO','01DMEAPG','01DME01','0201I01DMESSAO','Monitoramento das entregas de Material Cl VI junto aos fornecedores','Controle Preventivo','Acompanhamento do processo de aquisição internacional','Mitigar','Acompanhar a entrega do material junto ao fornecedor. Designar um integrante da DME para acompanhar pessoalmente, junto ao fornecedor, a entrega do material (empenho para chamar de seu).',40);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0201I0101DOMAPG','01DOMAPG','01DOM01','0201I01DOMAPG','Relatórios mensais de acompanhamento das Obras Paralisadas.','Controle Preventivo','Acompanhamento das principais obras usando a FIO e o OPUS.','Mitigar','Buscar reduzir o número de obras paralisadas, se necessário, estabelecendo contato com a "ponta da linha".',41);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0201I0102DMESSAO','01DMEAPG','01DME01','0201I01DMESSAO','Monitoramento das entregas de Material Cl VI junto aos fornecedores, após o prazo limite da entrega.','Controle de Detecção','Evitar o atraso na entrega do Material Cl VI.','Mitigar','Acompanhar a entrega do material junto ao fornecedor. Designar um integrante da DME para acompanhar pessoalmente, junto ao fornecedor, a entrega do material (empenho para chamar de seu).',42);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0201I0102DOMAPG','01DOMAPG','01DOC02','0201I01DOMAPG','Relatórios mensais de acompanhamento de obras paralisadas.','Controle de Detecção','Contingenciar as Obras Paralisadas.','Mitigar','Instaurar Processo Administrativo e, constatada qualquer inobservância prejudicial à Administração Pública, aplicar as sanções administrativas cabíveis. Comunicar o DEC e a autoridade patrocinadora (Gerente do Programa).',43);
INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0301I0101DOCEQPG2','01DOC01','01DOC02','0301I01DOCEQPG2','Acompanhar todas as Linhas de Controle do processo de PCF;\r\nBuscar a lavratura do TRD junto ao Concedente;\r\nAprovar a PCF antes de encaminhar ao concedente.','Controle Preventivo','Gestão do instrumento de parceria','Mitigar','Buscar reduzir as falhas nos procedimentos da PCF e do envio das informações para que os eventuais problemas sejam corrigidos antecipadamente',44);
