INSERT INTO "tratamento_monitoramento_controle" ("codigo", "responsavel_pelo_controle", "codprocesso", "codrisco", "controle", "categoria_do_controle", "plano_de_contingencia_associado", "estrategia_de_tratamento_do_risco", "descricao_da_estrategia_de_tratamento", "frequencia_de_revisao") VALUES ('0301I0102DOMAPG','02DOMAPG','01DOM03','0301I01DOMAPG','Relatórios mensais de acompanhamento da conclusão da obra pelo OPUS.','Controle de Detecção','Confirmar o TEREO no OPUS','Mitigar','Acompahar a conclusão da obra pelo OPUS.',47);
